    font-size:

      15px !important;

  }





  .erp-stat-label,

  .erp-stat-card .erp-stat-label {



    font-size:

      10px !important;

  }





  /* الاختصارات */



  .erp-quick-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;



    gap:

      8px;

  }





