  width: 100%;



  margin-bottom: 7px;



  color:

    var(--brand-text) !important;



  font-size: 13.5px;

  font-weight: 800;



  line-height: 1.45;

}





/* =========================================================

   12. CYCLE DESCRIPTION

========================================================= */



.erp-cycle-description {



