}





[dir="ltr"]

.erp-modal-close {



  right: 12px;

}





/* =========================================================

   42. MODAL CONTENT

========================================================= */



.erp-modal-header {



  display: flex;



  align-items: center;



  gap: 11px;



  margin-bottom:

    15px;

}





.erp-modal-icon {



  font-size:

    28px;



