    rgba(15, 132, 181, 0.40);

}





/*

   في الوضع الداكن نقلل وضوح Pattern

*/



[data-theme="dark"]

.erp-dashboard-wrapper::before,



html[data-theme="dark"]

.erp-dashboard-wrapper::before {



  opacity: 0.025;

}





[data-theme="dark"]

.erp-cycle-container,



html[data-theme="dark"]

.erp-cycle-container,



[data-theme="dark"]

.erp-overview-container,



html[data-theme="dark"]

.erp-overview-container,



[data-theme="dark"]

.erp-cycle-card,



html[data-theme="dark"]

.erp-cycle-card,



[data-theme="dark"]

.erp-card,



html[data-theme="dark"]

.erp-card,



[data-theme="dark"]

.erp-stat-card,



html[data-theme="dark"]

.erp-stat-card {



