/* البطاقة تتمدد حسب عرض العمود */

.erp-cycle-card {

  width: 100%;



  min-width: 0;



  min-height: 180px;

}



/* =========================================================

   9. PURCHASE CYCLE CARD

========================================================= */



.erp-cycle-card {



  --cycle-color:

    var(--brand-primary);



  --cycle-soft:

    var(--brand-soft);



  position: relative;



  display: flex;



  flex-direction: column;



  align-items: center;

  justify-content: flex-start;



  width: 100%;



  min-width: 0;

  min-height: 180px;



  padding: 17px 11px 15px;



  overflow: hidden;



  border:

    1px solid var(--brand-border);



  border-radius: 14px;



  outline: none;



  background:

    rgba(255, 255, 255, 0.96);



  color:

    var(--brand-text) !important;



  font-family: inherit;



  text-align: center;



  cursor: pointer;



  transition:

    transform 0.20s ease,

    border-color 0.20s ease,

    box-shadow 0.20s ease;

}





.erp-cycle-card::before {



  content: "";



  position: absolute;



  inset: 0;



  border-radius: inherit;



  background:

