/* =========================================================

   39. MODAL OVERLAY

========================================================= */



.erp-modal-overlay {



  position: fixed;



  inset: 0;



  z-index:

    99999 !important;



  display: flex;



  align-items: center;

  justify-content: center;



  padding: 20px;



  background:

    rgba(12, 27, 54, 0) !important;



  transition:

    background 0.28s ease;

}





.erp-modal-overlay.is-visible {



  background:

    rgba(12, 27, 54, 0.52) !important;

}





/* =========================================================

   40. MODAL BOX

========================================================= */



.erp-modal-box {



  position: relative;



  width: 100%;



  max-width: 480px;

  max-height: 85vh;



  padding:

    28px 24px;



  overflow-y: auto;



  border:

    1px solid var(--brand-border);



  border-radius:

    16px;



  background:

    #ffffff !important;



  box-shadow:

