  opacity: 0;



  transform:

    translateY(24px)

    scale(0.97);



  transition:

    opacity 0.28s ease,

    transform 0.28s ease;

}





.erp-modal-overlay.is-visible

.erp-modal-box {



  opacity: 1;



  transform:

    translateY(0)

    scale(1);

}





/* =========================================================

   41. MODAL CLOSE

========================================================= */



.erp-modal-close {



  position: absolute;



  top: 12px;



  display: flex;



  align-items: center;

  justify-content: center;



  width: 32px;

  height: 32px;



  border: 0;



  border-radius:

    8px;



  background:

    var(--brand-soft);



  color:

    var(--brand-primary) !important;



  font-size:

    15px;



  cursor:

    pointer;

}





[dir="rtl"]

.erp-modal-close {



  left: 12px;

}





[dir="ltr"]

.erp-modal-close {



  right: 12px;

}





/* =========================================================

   42. MODAL CONTENT

========================================================= */



.erp-modal-header {



  display: flex;



  align-items: center;



  gap: 11px;



  margin-bottom:

    15px;

}





.erp-modal-icon {



  font-size:

    28px;



  line-height:

    1;

}





.erp-modal-title {



  margin: 0;



  color:

    var(--brand-text) !important;



  font-size:

    18px;



  font-weight:

    800;

}





