    -webkit-mask-size:

      115px auto;



    mask-size:

      115px auto;



    opacity:

      0.025;

  }





  /* دورة المشتريات */



  .erp-cycle-container {



    padding:

      12px;

  }





  .erp-cycle-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr));



    gap:

