      36px;



    margin-bottom:

      10px;



    font-size:

      15px;

  }





  .erp-cycle-card-title {



    font-size:

      12px;

  }





  .erp-cycle-description {



    font-size:

      9.5px;



    line-height:

      1.55;

  }





