    gap:

      9px;

  }





  .erp-stat-card {



    min-height:

      76px;



    padding:

      11px;



    gap:

      8px;

  }





  .erp-stat-icon {



    width:

      36px;



    height:

      36px;



    flex-basis:

      36px;



    font-size:

      9px !important;

  }





  .erp-stat-value,

  .erp-stat-card .erp-stat-value {



    font-size:

      15px !important;

  }





  .erp-stat-label,

  .erp-stat-card .erp-stat-label {



    font-size:

      10px !important;

  }





  /* الاختصارات */



  .erp-quick-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;



    gap:

      8px;

  }





  .erp-quick-btn {



    min-height:

      43px;



    padding:

      9px 7px;



    font-size:

      11.5px;

  }





  /* التقارير */



  .erp-dashboard-grid {



    grid-template-columns:

      1fr !important;



    gap:

      11px;

  }





  .erp-card.is-open {



    transform:

      translateY(-2px);

  }





  /* الفوتر */



  .erp-footer {



    --footer-font-size:

      13px;



    margin-top:

      26px;



    padding-top:

      16px;

  }





  .erp-footer-inner {



    flex-direction:

      column;



    gap:

      8px;

  }





  .erp-footer-item {



    justify-content:

      center;

  }





  .erp-footer-icon {



    font-size:

      15px !important;

  }





  .erp-footer-sep {



    display:

      none;

  }





  /* المودال */



  .erp-modal-overlay {



    align-items:

      flex-end;



    padding:

      10px;

  }





  .erp-modal-box {



    max-height:

      82vh;



    padding:

      22px 17px;



    border-radius:

      16px 16px 0 0;

  }

}

