========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {



    position: relative;



    z-index: 2;

}

/* =========================================================

   إبقاء جميع عناصر الداشبورد فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {

    position: relative;

    z-index: 2;

}



/* =========================================================

   5. CONTENT LAYER

   جميع المحتويات تظهر فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {



  position: relative;



  z-index: 2;

}





.erp-dashboard-content,

.erp-module-section,

.erp-dashboard-grid {



  background: transparent !important;

}





/* =========================================================

   6. SECTION TITLE

========================================================= */



.erp-section-title {



  position: relative;



  display: flex;

  align-items: center;



  min-height: 36px;



  margin: 0 0 16px;



  padding: 0 0 10px;



  border-bottom:

    1px solid var(--brand-border);



  color:

    var(--brand-text) !important;



  font-size: 18px;

  font-weight: 700;



  line-height: 1.4;

}





.erp-section-title::after {



  content: "";



  position: absolute;



  bottom: -1px;



  width: 52px;

  height: 2px;



  border-radius: 20px;



  background: var(--brand-primary);

}





.erp-dashboard-rtl

.erp-section-title::after {



  right: 0;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-section-title::after {



  left: 0;

}





/* =========================================================

   7. PURCHASE CYCLE SECTION

========================================================= */



.erp-purchase-cycle-section {



  margin: 18px 0 24px;

}





.erp-cycle-container {



  position: relative;



  padding: 18px 18px 20px;



  border:

    1px solid var(--brand-border);



  border-radius: 16px;



  /*

     شبه معتم حتى يبقى الـ Pattern ظاهراً بخفة

  */



  background:

    rgba(255, 255, 255, 0.94);



  box-shadow:

    0 5px 18px rgba(36, 59, 99, 0.06);

}





.erp-cycle-title {



  margin-bottom: 20px;

}





/* =========================================================

   SALES / PURCHASE CYCLE GRID

   توزيع البطاقات على كامل عرض الصفحة

========================================================= */



.erp-cycle-grid {

  display: grid;



  grid-template-columns:

    repeat(5, minmax(0, 1fr));



  gap: 18px;



  width: 100%;



  align-items: stretch;

}





.erp-cycle-item {

  position: relative;



  display: flex;



  width: 100%;



  min-width: 0;

}





/* البطاقة تتمدد حسب عرض العمود */

.erp-cycle-card {

  width: 100%;



  min-width: 0;



  min-height: 180px;

}



/* =========================================================

   9. PURCHASE CYCLE CARD

========================================================= */



.erp-cycle-card {



  --cycle-color:

    var(--brand-primary);



  --cycle-soft:

    var(--brand-soft);



  position: relative;



  display: flex;



  flex-direction: column;



  align-items: center;

  justify-content: flex-start;



  width: 100%;



  min-width: 0;

  min-height: 180px;



  padding: 17px 11px 15px;



  overflow: hidden;



  border:

    1px solid var(--brand-border);



  border-radius: 14px;



  outline: none;



  background:

    rgba(255, 255, 255, 0.96);



  color:

    var(--brand-text) !important;



  font-family: inherit;



  text-align: center;



  cursor: pointer;



  transition:

    transform 0.20s ease,

    border-color 0.20s ease,

    box-shadow 0.20s ease;

}





.erp-cycle-card::before {



  content: "";



  position: absolute;



  inset: 0;



  border-radius: inherit;



  background:

    var(--cycle-soft);



  opacity: 0.42;



  pointer-events: none;

}





.erp-cycle-card::after {



  content: "";



  position: absolute;



  right: 0;

  bottom: 0;



  width: 0;

  height: 3px;



  background:

    var(--cycle-color);



  transition:

    width 0.25s ease;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-cycle-card::after {



  right: auto;

  left: 0;

}





.erp-cycle-card > * {



  position: relative;



  z-index: 2;

}





@media (hover: hover) {



  .erp-cycle-card:hover {



    transform:

      translateY(-4px);



    border-color:

      var(--cycle-color);



    box-shadow:

      0 12px 28px rgba(36, 59, 99, 0.12);

  }





  .erp-cycle-card:hover::after {



    width: 100%;

  }

}





/* =========================================================

   10. CYCLE NUMBER

========================================================= */



.erp-cycle-number {



  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 42px;

  height: 42px;



  flex: 0 0 42px;



  margin-bottom: 14px;



  border-radius: 50%;



  background:

    var(--cycle-color);



  color:

    #ffffff !important;



  font-size: 18px;

  font-weight: 800;



  line-height: 1;



  box-shadow:

    0 5px 14px rgba(36, 59, 99, 0.12);

}





/* =========================================================

   11. CYCLE TITLE

========================================================= */



.erp-cycle-card-title {



  display: block;



  width: 100%;



  margin-bottom: 7px;



  color:

    var(--brand-text) !important;



  font-size: 13.5px;

  font-weight: 800;



  line-height: 1.45;

}





/* =========================================================

   12. CYCLE DESCRIPTION

========================================================= */



.erp-cycle-description {



  display: block;



  width: 100%;



  color:

    var(--brand-muted) !important;



  font-size: 10.5px;

  font-weight: 500;



  line-height: 1.65;

}





/* =========================================================

   13. CYCLE BRAND COLORS

========================================================= */



.erp-cycle-card.cycle-tone-1 {



  --cycle-color:

    var(--brand-primary);



  --cycle-soft:

    var(--brand-soft);

}





.erp-cycle-card.cycle-tone-2 {



  --cycle-color:

    var(--brand-secondary);



  --cycle-soft:

    var(--brand-soft-secondary);

}





.erp-cycle-card.cycle-tone-3 {



  --cycle-color:

    var(--brand-accent);



  --cycle-soft:

    var(--brand-soft-accent);

}





.erp-cycle-card.cycle-tone-4 {



  --cycle-color:

    var(--brand-purple);



  --cycle-soft:

    var(--brand-soft-purple);

}





/* =========================================================

   14. CYCLE ARROW

========================================================= */



.erp-cycle-arrow {



  position: absolute;



  top: 50%;



  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 20px;

  height: 20px;



  color:

    var(--brand-primary) !important;



  font-size: 20px;

  font-weight: 800;



  line-height: 1;



  opacity: 0.55;



  transform:

    translateY(-50%);



  pointer-events: none;



  z-index: 10;

}





.erp-dashboard-rtl

.erp-cycle-arrow {



  left: -17px;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-cycle-arrow {



  right: -17px;

}





/* =========================================================

   15. OVERVIEW SECTION

========================================================= */



.erp-stats-section {



  margin: 0 0 24px;

}





.erp-overview-container {



  padding: 18px;



  border:

    1px solid var(--brand-border);



  border-radius: 16px;



  background:

    rgba(255, 255, 255, 0.94);



  box-shadow:

    0 5px 18px rgba(36, 59, 99, 0.06);

}





/* =========================================================

   16. STATS GRID

========================================================= */



.erp-stats-grid {



  display: grid !important;



  grid-template-columns:

    repeat(4, minmax(0, 1fr)) !important;



  gap: 14px;



  margin: 0;

}





/* =========================================================

   17. STAT CARD

========================================================= */



.erp-stat-card {



  display: flex;



  align-items: center;



  gap: 13px;



  min-width: 0;



  min-height: 88px;



  padding: 16px 18px;



  border:

    1px solid var(--brand-border);



  border-radius: 14px;



  background:

    rgba(255, 255, 255, 0.96);



  box-shadow:

    0 4px 14px rgba(36, 59, 99, 0.05);



