    border-color:

      var(--brand-border-strong);



    box-shadow:

      0 10px 26px rgba(36, 59, 99, 0.10);

  }

}





/* =========================================================

   18. STAT ICON

========================================================= */



.erp-stat-icon {



  display: flex;



  align-items: center;

  justify-content: center;



  width: 46px;

  height: 46px;



  flex: 0 0 46px;



  border-radius: 12px;



  background:

    var(--brand-soft);



