}





.erp-stat-card.overview-tone-2

.erp-stat-icon {



  background:

    var(--brand-soft-secondary);



  color:

    var(--brand-secondary) !important;

}





.erp-stat-card.overview-tone-3

.erp-stat-icon {



  background:

    var(--brand-soft-accent);



  color:

    var(--brand-accent) !important;

}





.erp-stat-card.overview-tone-4

.erp-stat-icon {



  background:

    var(--brand-soft-purple);



  color:

    var(--brand-purple) !important;

}





/* =========================================================

   19. STAT INFO

========================================================= */



.erp-stat-info {



  display: flex;



  flex-direction: column;



  gap: 3px;



  min-width: 0;



  color:

    var(--brand-text) !important;

}





.erp-stat-value,

.erp-stat-card .erp-stat-value {



  color:

    var(--brand-text) !important;



  font-size:

    20px !important;



  font-weight:

    800 !important;



  line-height: 1.3;



  direction: ltr;

}





.erp-stat-label,

.erp-stat-card .erp-stat-label {



  color:

    var(--brand-text) !important;



  font-size:

    12px !important;



  font-weight:

    600 !important;



  line-height: 1.45;

}





/* =========================================================

   20. QUICK ACTIONS

   تم إبقاء تصميم الاختصارات كما كان

========================================================= */



.erp-quick-actions {



  margin-bottom: 24px;

}





/* =========================================================

   21. QUICK ACTIONS GRID

========================================================= */



.erp-quick-grid {



  display: grid !important;



  grid-template-columns:

    repeat(4, minmax(0, 1fr)) !important;



  gap: 12px;

}





/* =========================================================

   22. QUICK BUTTON

========================================================= */



.erp-quick-btn {



  display: flex;



  align-items: center;

  justify-content: center;



  min-height: 48px;



  padding:

    11px 14px;



  border:

    1px solid var(--brand-border);



  border-radius: 10px;



  outline: none;



  background:

    var(--brand-soft);



  color:

    var(--brand-primary) !important;



  font-family: inherit;



  font-size: 15px;

  font-weight: 700;



  line-height: 1.4;



  text-align: center;



  cursor: pointer;



  transition:

    transform 0.18s ease,

    background-color 0.18s ease,

    border-color 0.18s ease,

    color 0.18s ease,

    box-shadow 0.18s ease;

}





.erp-quick-btn:nth-child(1) {



  background:

    var(--brand-soft);

}





.erp-quick-btn:nth-child(2) {



  background:

    var(--brand-soft-secondary);

}





.erp-quick-btn:nth-child(3) {



  background:

    var(--brand-soft-accent);

}





.erp-quick-btn:nth-child(4) {



  background:

    var(--brand-soft-purple);

}





.erp-quick-btn,

.erp-quick-btn .erp-quick-label {



  color:

    var(--brand-primary) !important;

}





@media (hover: hover) {



  .erp-quick-btn:hover {



    transform:

      translateY(-2px);



    color:

      var(--brand-secondary) !important;



    border-color:

      var(--brand-secondary);



    background:

      rgba(15, 132, 181, 0.10);



    box-shadow:

      0 6px 16px rgba(56, 103, 174, 0.12);

  }

}





.erp-quick-btn:active {



  transform:

    scale(0.98);

}





.erp-quick-label {



  width: 100%;



  white-space: normal;



  text-align: center;

}





/* =========================================================

   23. MODULE SECTION

========================================================= */



.erp-module-section {



  margin-top: 24px;

}





/* =========================================================

   24. REPORT CARDS GRID

========================================================= */



.erp-dashboard-grid {



  display: grid !important;



  grid-template-columns:

    repeat(3, minmax(0, 1fr)) !important;



  align-items: start;



  gap: 16px;



  width: 100%;



  overflow: visible;

}





/* =========================================================

   25. REPORT CARD

========================================================= */



.erp-card {



  --erp-accent:

    var(--brand-primary);



  --erp-soft:

    var(--brand-soft);



  position: relative;



  z-index: 1;



  min-width: 0;



  min-height: 74px;

  max-height: 74px;



  padding:

    0 16px;



  overflow: hidden;



  border:

    1px solid var(--brand-border);



  border-radius: 14px;



  background:

    rgba(255, 255, 255, 0.95);



  color:

    var(--brand-text) !important;



  box-shadow:

    0 5px 16px rgba(36, 59, 99, 0.06);



  transition:

    max-height 0.4s ease,

    transform 0.28s ease,

    box-shadow 0.28s ease,

    border-color 0.28s ease,

    padding-bottom 0.28s ease;

}





.erp-card::before {



  content: "";



  position: absolute;



  inset: 0;



  z-index: 0;



  background:

    var(--erp-soft);



  opacity: 0;



  pointer-events: none;



  transition:

    opacity 0.25s ease;

}





.erp-card::after {



  content: "";



  position: absolute;



  right: 0;

  bottom: 0;



  z-index: 4;



  width: 0;

  height: 3px;



  background:

    var(--erp-accent);



  transition:

    width 0.3s ease;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-card::after {



  right: auto;

  left: 0;

}





/* =========================================================

   26. CARD BRAND TONES

========================================================= */



.erp-card.tone-0 {



  --erp-accent:

    var(--brand-primary);



  --erp-soft:

    var(--brand-soft);

}





.erp-card.tone-1 {



  --erp-accent:

    var(--brand-secondary);



  --erp-soft:

    var(--brand-soft-secondary);

}





.erp-card.tone-2 {



  --erp-accent:

    var(--brand-accent);



  --erp-soft:

    var(--brand-soft-accent);

}





.erp-card.tone-3 {



  --erp-accent:

    var(--brand-purple);



  --erp-soft:

    var(--brand-soft-purple);

}





.erp-card.tone-4 {



  --erp-accent:

    var(--brand-primary);



  --erp-soft:

    var(--brand-soft);

}





/* =========================================================

   27. CARD OPEN

========================================================= */



.erp-card.is-open {



  z-index: 30;



  max-height: 590px;



  padding-bottom: 15px;



  border-color:

    var(--erp-accent);



  transform:

    translateY(-5px);



  box-shadow:

    0 18px 40px rgba(36, 59, 99, 0.14);

}





.erp-card.is-open::before {



  opacity: 1;

}





.erp-card.is-open::after {



  width: 100%;

}











/* =========================================================

   28. CARD HEADING

========================================================= */



.erp-card-heading {



  position: relative;



  z-index: 2;



  display: flex;

  align-items: center;



  gap: 8px;



