      "هيكل الراتب",



    "Salary Component":

      "مكون الراتب",



    "Employee Advance":

      "سلفة موظف",



    "Expense Claim":

      "مطالبة مصروفات",



    "Job Opening":

      "شاغر وظيفي",



    "Job Applicant":

      "متقدم للوظيفة",



    "Job Offer":

      "عرض وظيفي",



    "Appraisal":

      "تقييم الموظف",



    "Appraisal Cycle":

      "دورة التقييم",



    "Employee Performance Feedback":

      "ملاحظات أداء الموظف",



    "Employee Onboarding":

      "تهيئة الموظف",



    "Employee Separation":

      "إنهاء خدمة الموظف",



    "Employee Leave Balance":

      "رصيد إجازات الموظفين",



    "Monthly Attendance Sheet":

      "كشف الحضور الشهري",



    "Salary Register":

      "سجل الرواتب"



  };





  /* =========================================================

     8. ROUTE TYPES

  ========================================================= */



  const treeDocs =

    new Set([

      "Department"

    ]);





  const reportNames =

    new Set([

      "Employee Leave Balance",

      "Monthly Attendance Sheet",

      "Salary Register"

    ]);





  /* =========================================================

     9. TRANSLATE

  ========================================================= */



  function translate(name) {



    if (!isArabic)

      return name;



    return (

      arabicFallback[name] ||

      name

    );

  }





  /* =========================================================

     10. ROUTING

  ========================================================= */



  function openRoute(name) {



    try {



      if (reportNames.has(name)) {



        frappe.set_route(

          "query-report",

          name

        );



        return;

      }





      if (treeDocs.has(name)) {



        frappe.set_route(

          "Tree",

          name

        );



        return;

      }





      frappe.set_route(

        "List",

        name

      );



    } catch (e) {



      console.error(

        "HR Route Error:",

        name,

        e

      );



    }

  }





  function newDoc(doctype) {



    try {



      frappe.new_doc(

        doctype

      );



    } catch (e) {



      console.error(

        "HR New Doc Error:",

        doctype,

        e

      );



    }

  }





  /* =========================================================

     11. GENERIC SELECTOR

  ========================================================= */



  function showSelector(titleAr, titleEn, items) {



    const overlay =

      document.createElement("div");



    overlay.className =

      "erp-modal-overlay";



    overlay.setAttribute(

      "dir",

      isArabic ? "rtl" : "ltr"

    );





    overlay.innerHTML = `



      <div class="erp-modal-box">



        <button

          type="button"

          class="erp-modal-close"

          data-selector-close

        >

          ✕

        </button>



        <div class="erp-modal-header">



          <span class="erp-modal-icon">

            👤

          </span>



          <h3 class="erp-modal-title">

            ${

              isArabic

                ? titleAr

                : titleEn

            }

          </h3>



        </div>





        <div

          class="erp-quick-grid"

          style="

            margin-top:18px;

            grid-template-columns:

            repeat(${items.length}, minmax(0,1fr)) !important;

          "

        >



          ${items

            .map(

              (item, index) => `



                <button

                  type="button"

                  class="erp-quick-btn"

                  data-selector-index="${index}"

                >



                  ${

                    escapeHtml(

                      isArabic

                        ? item.labelAr

                        : item.labelEn

                    )

                  }



                </button>



              `

            )

            .join("")}



        </div>



      </div>



    `;





    root.appendChild(overlay);





    requestAnimationFrame(() => {



      overlay.classList.add(

        "is-visible"

      );



    });





    overlay

      .querySelector("[data-selector-close]")

      ?.addEventListener(

        "click",

        () => overlay.remove()

      );





    overlay.addEventListener(

      "click",

      event => {



        if (event.target === overlay)

          overlay.remove();



      }

    );





    overlay

      .querySelectorAll(

        "[data-selector-index]"

      )

      .forEach(button => {



        button.addEventListener(

          "click",

          () => {



            const item =

              items[

                Number(

                  button.dataset.selectorIndex

                )

              ];





            overlay.remove();





            if (!item)

              return;





            if (item.action === "new") {



              newDoc(

                item.doctype

              );



              return;

            }





            openRoute(

              item.doctype

            );



          }

        );



      });



  }





  /* =========================================================

     12. RENDER HR CYCLE

  ========================================================= */



  function renderHRCycle() {



    if (!hrCycle)

      return;





    hrCycle.innerHTML = `



      <section class="erp-cycle-container">



        <h2

          class="

            erp-section-title

            erp-cycle-title

          "

        >

          ${

            isArabic

              ? "دورة الموارد البشرية"

              : "HR Management Flow"

          }

        </h2>





        <div

          class="erp-cycle-grid"

          style="

            grid-template-columns:

            repeat(

              ${hrCycleCards.length},

              minmax(0,1fr)

            );

          "

        >



          ${hrCycleCards

            .map(

              (card, index) => `



                <div class="erp-cycle-item">



                  <button

                    type="button"

                    class="

                      erp-cycle-card

                      cycle-tone-${(index % 4) + 1}

                    "

                    data-hr-cycle="${index}"

                  >



                    <span class="erp-cycle-number">

                      ${card.step}

                    </span>



                    <span class="erp-cycle-card-title">



                      ${escapeHtml(

                        isArabic

                          ? card.labelAr

                          : card.labelEn

                      )}



                    </span>



                    <span class="erp-cycle-description">



                      ${escapeHtml(

                        isArabic

                          ? card.descriptionAr

                          : card.descriptionEn

                      )}



                    </span>



                  </button>





                  ${

                    index <

                    hrCycleCards.length - 1



                      ? `

                        <span

                          class="erp-cycle-arrow"

                          aria-hidden="true"

                        >

                          ${isArabic ? "←" : "→"}

                        </span>

                      `

                      : ""

                  }



                </div>



              `

            )

            .join("")}



        </div>



      </section>



    `;





    hrCycle.addEventListener(

      "click",

      event => {



        const element =

          event.target.closest(

            "[data-hr-cycle]"

          );





        if (!element)

          return;





        const card =

          hrCycleCards[

            Number(

              element.dataset.hrCycle

            )

          ];





        if (!card)

          return;





        if (card.action === "new") {



          newDoc(card.doctype);

          return;

        }





        if (

          card.action ===

          "organization-selector"

        ) {



          showSelector(



            "الهيكل الوظيفي",

            "Organization Structure",



            [

              {

                action: "route",

                doctype: "Department",

                labelAr: "الأقسام",

                labelEn: "Departments"

              },



              {

                action: "route",

                doctype: "Designation",

                labelAr: "المسميات الوظيفية",

                labelEn: "Designations"

              },



              {

                action: "route",

                doctype: "Branch",

                labelAr: "الفروع",

                labelEn: "Branches"

              }

            ]



          );



          return;

        }





        if (

          card.action ===

          "attendance-selector"

        ) {



          showSelector(



            "الحضور والانصراف",

            "Attendance",



            [

              {

                action: "route",

                doctype: "Attendance",

                labelAr: "الحضور",

                labelEn: "Attendance"

              },



              {

                action: "route",

                doctype: "Employee Checkin",

                labelAr: "دخول وانصراف الموظف",

                labelEn: "Employee Checkin"

              },



              {

                action: "route",

                doctype: "Shift Assignment",

                labelAr: "تعيين الورديات",

                labelEn: "Shift Assignment"

              }

            ]



          );



          return;

        }





        if (

          card.action ===

          "payroll-selector"

        ) {



          showSelector(



            "الرواتب",

            "Payroll",



            [

              {

                action: "route",

                doctype: "Payroll Entry",

                labelAr: "مسير الرواتب",

                labelEn: "Payroll Entry"

              },



              {

                action: "route",

                doctype: "Salary Slip",

                labelAr: "قسائم الرواتب",

                labelEn: "Salary Slips"

              },



              {

                action: "route",

                doctype: "Salary Structure",

                labelAr: "هياكل الرواتب",

                labelEn: "Salary Structures"

              }

            ]



          );



          return;

        }





        if (

          card.action ===

          "finance-selector"

        ) {



          showSelector(



            "السلف والمصروفات",

            "Advances & Expenses",



            [

              {

                action: "route",

                doctype: "Employee Advance",

                labelAr: "سلف الموظفين",

                labelEn: "Employee Advances"

              },



              {

                action: "route",

                doctype: "Expense Claim",

                labelAr: "مطالبات المصروفات",

                labelEn: "Expense Claims"

              }

            ]



          );



          return;

        }





        openRoute(

          card.doctype

        );



      }

    );



  }





  /* =========================================================

     13. RENDER STATS

  ========================================================= */



  function renderStats() {



    if (!statsSection)

      return;





    statsSection.innerHTML = `



      <section class="erp-overview-container">



        <h2 class="erp-section-title">

          ${

            isArabic

              ? "نظرة عامة"

              : "Overview"

          }

        </h2>





        <div class="erp-stats-grid">



          ${statsCards

            .map(

              (card, index) => `



                <div

                  class="

                    erp-stat-card

                    overview-tone-${index + 1}

                  "

                >



                  <div class="erp-stat-icon">

                    ${escapeHtml(card.short)}

                  </div>





                  <div class="erp-stat-info">



                    <span

                      class="erp-stat-value"

                      data-hr-stat="${card.id}"

                    >

                      0

                    </span>





                    <span class="erp-stat-label">



                      ${escapeHtml(

                        isArabic

                          ? card.labelAr

                          : card.labelEn

                      )}



                    </span>



                  </div>



                </div>



              `

            )

            .join("")}



        </div>



      </section>



    `;





    statsCards.forEach(card => {



      Promise

        .resolve()

        .then(() => card.fetch())

        .then(value => {



          const element =

            statsSection.querySelector(

              `[data-hr-stat="${card.id}"]`

            );





          if (element) {



            element.textContent =

              formatNumber(value);



          }



        })

        .catch(error => {



          console.error(

            "HR Stat Error:",

            card.id,

            error

          );



        });



    });



  }





  /* =========================================================

     14. QUICK ACTIONS

  ========================================================= */



  function renderQuickActions() {



    if (!quickActions)

      return;





    quickActions.innerHTML = `



      <h2 class="erp-section-title">

        ${

          isArabic

            ? "اختصارات سريعة"

            : "Quick Actions"

        }

      </h2>





      <div class="erp-quick-grid">



        ${quickActionButtons

          .map(

            (button, index) => `



              <button

                type="button"

                class="erp-quick-btn"

                data-hr-quick="${index}"

              >



                <span class="erp-quick-label">



                  ${escapeHtml(

                    isArabic

                      ? button.labelAr

                      : button.labelEn

                  )}



                </span>



              </button>



            `

          )

          .join("")}



      </div>



    `;





    quickActions.addEventListener(

      "click",

      event => {



        const element =

          event.target.closest(

            "[data-hr-quick]"

          );





        if (!element)

          return;





        const button =

          quickActionButtons[

            Number(

              element.dataset.hrQuick

            )

          ];





        if (!button)

          return;





        newDoc(

          button.doctype

        );



      }

    );



  }





  /* =========================================================

     15. RENDER SECTIONS

  ========================================================= */



  function renderSections() {



    if (!content)

      return;





    content.innerHTML =

      sections

        .map(

          (section, sectionIndex) => {



            const cards =

              section[1]

                .map(

                  (card, cardIndex) => {



                    const links =

                      card[2]

                        .map(

                          item => `



                            <div class="erp-link-row">



                              <button

                                type="button"

                                class="erp-link"

                                data-hr-route="${escapeHtml(item)}"

                              >



                                <span class="erp-link-text">

                                  ${escapeHtml(translate(item))}

                                </span>



                                <span class="erp-link-arrow">

                                  ${isArabic ? "←" : "→"}

                                </span>



                              </button>



                            </div>



                          `

                        )

                        .join("");





                    return `



                      <article

                        class="

                          erp-card

                          tone-${(sectionIndex + cardIndex) % 5}

                        "

                        data-hr-card

                      >



                        <button

                          type="button"

                          class="erp-card-heading"

                          data-hr-toggle

                          aria-expanded="false"

                        >



                          <span class="erp-icon">

                            ${card[1]}

                          </span>



                          <span class="erp-card-title">

                            ${escapeHtml(translate(card[0]))}

                          </span>



                          <span class="erp-card-chevron">

                            ⌄

                          </span>



                        </button>





                        <div class="erp-card-links">

                          ${links}

                        </div>



                      </article>



                    `;



                  }

                )

                .join("");





            return `



              <section class="erp-module-section">



                <h2 class="erp-section-title">

                  ${escapeHtml(translate(section[0]))}

                </h2>



                <div class="erp-dashboard-grid">

                  ${cards}

                </div>



              </section>



            `;



          }

        )

        .join("");





    content.addEventListener(

      "click",

      event => {





        const routeButton =

          event.target.closest(

            "[data-hr-route]"

          );





        if (routeButton) {



          event.preventDefault();



          openRoute(

            routeButton.dataset.hrRoute

          );



          return;

        }





        const toggle =

          event.target.closest(

            "[data-hr-toggle]"

          );





        if (!toggle)

          return;





        const selectedCard =

          toggle.closest(

            "[data-hr-card]"

          );





        if (!selectedCard)

          return;





        const shouldOpen =

          !selectedCard

            .classList

            .contains(

              "is-open"

            );





        content

          .querySelectorAll(

            "[data-hr-card]"

          )

          .forEach(card => {



            if (

              card !== selectedCard

            ) {



              card.classList.remove(

                "is-open"

              );



            }



          });





        selectedCard

          .classList

          .toggle(

            "is-open",

            shouldOpen

          );



      }

    );



  }





  /* =========================================================

     16. FOOTER

  ========================================================= */



  function renderFooter() {



    if (!footerEl)

      return;





    footerEl.innerHTML = `



      <div class="erp-footer-inner">



        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ☎

          </span>



          <span class="erp-footer-label">

            ${

              isArabic

                ? "الهاتف الموحد:"

                : "Phone:"

            }

          </span>



          <a

            href="tel:0115110455"

            class="erp-footer-link"

            dir="ltr"

          >

            0115110455

          </a>



        </div>





        <span class="erp-footer-sep">

          |

        </span>





        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ✉

          </span>



          <span class="erp-footer-label">

            ${

              isArabic

                ? "البريد الإلكتروني:"

                : "Email:"

            }

          </span>



          <a

            href="mailto:sales@mubtkir.com"

            class="erp-footer-link"

          >

            sales@mubtkir.com

          </a>



        </div>





        <span class="erp-footer-sep">

          |

        </span>





        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ◎

          </span>



          <span class="erp-footer-label">

            ${

              isArabic

                ? "الموقع:"

                : "Website:"

            }

          </span>



          <a

            href="https://www.mubtkir.com"

            class="erp-footer-link"

            target="_blank"

            rel="noopener"

          >

            www.mubtkir.com

          </a>



        </div>



      </div>



    `;



  }





  /* =========================================================

     17. INIT

  ========================================================= */



  try {



    renderHRCycle();



  } catch (e) {



    console.error(

      "HR Cycle Error:",

      e

    );



  }





  try {



    renderStats();



  } catch (e) {



    console.error(

      "HR Stats Error:",

      e

    );



  }





  try {



    renderQuickActions();



  } catch (e) {



    console.error(

      "HR Quick Actions Error:",

      e

    );



  }





  try {



    renderSections();



  } catch (e) {



    console.error(

      "HR Sections Error:",

      e

    );



  }





  try {



    renderFooter();



  } catch (e) {



    console.error(

      "HR Footer Error:",

      e

    );



  }



})();

style:
/* =========================================================

   MUBTKIR ERP — BUYING WORKSPACE

   Unified Professional Brand Theme

   لوحة تحكم قسم المشتريات

========================================================= */





/* =========================================================

   1. ROOT + BRAND COLORS

   ألوان الهوية الرسمية

========================================================= */



.erp-dashboard-wrapper {



  --brand-primary: #3867AE;

  --brand-secondary: #0F84B5;

  --brand-accent: #0BA1B8;

  --brand-purple: #644DA6;



  --brand-text: #243B63;

  --brand-muted: #66758A;



  --brand-border: rgba(56, 103, 174, 0.22);

  --brand-border-strong: rgba(56, 103, 174, 0.38);



  --brand-soft: rgba(56, 103, 174, 0.07);

  --brand-soft-secondary: rgba(15, 132, 181, 0.07);

  --brand-soft-accent: rgba(11, 161, 184, 0.07);

  --brand-soft-purple: rgba(100, 77, 166, 0.07);



  position: relative;

  isolation: isolate;



  width: 100%;



  padding: 14px 16px 36px;



  overflow: visible;



  color: var(--brand-text);

}





/* =========================================================

   2. FONT

========================================================= */



.erp-dashboard-wrapper,

.erp-dashboard-wrapper * {



  box-sizing: border-box;



  font-family:

    "Tajawal",

    "Inter",

    Arial,

    sans-serif !important;

}





/* =========================================================

   3. RTL

========================================================= */



.erp-dashboard-wrapper.erp-dashboard-rtl {



  direction: rtl;

  text-align: right;

}





/* =========================================================

   BACKGROUND

   صورة واحدة في الخلفية بدون تكرار

========================================================= */



.erp-dashboard-bg {

    position: absolute !important;



    top: 50px;

    left: 50%;



    /* حجم الصورة */

    width: 78%;

    max-width: 1200px;



    height: auto;



    transform: translateX(-50%);



    /* الشفافية */

    opacity: 0.03;



    object-fit: contain;



    pointer-events: none;

    user-select: none;



    z-index: 0;

}





/* الحاوية الرئيسية */

.erp-dashboard-wrapper {

    position: relative !important;

    isolation: isolate;

}





/* المحتوى فوق الخلفية */

.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {

    position: relative !important;

    z-index: 2;

}



/* =========================================================

   المحتوى فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {



    position: relative;



    z-index: 2;

}

/* =========================================================

   إبقاء جميع عناصر الداشبورد فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {

    position: relative;

    z-index: 2;

}



/* =========================================================

   5. CONTENT LAYER

   جميع المحتويات تظهر فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {



  position: relative;



  z-index: 2;

}





.erp-dashboard-content,

.erp-module-section,

.erp-dashboard-grid {



  background: transparent !important;

}





/* =========================================================

   6. SECTION TITLE

========================================================= */



.erp-section-title {



  position: relative;



  display: flex;

  align-items: center;



  min-height: 36px;



  margin: 0 0 16px;



  padding: 0 0 10px;



  border-bottom:

    1px solid var(--brand-border);



  color:

    var(--brand-text) !important;



  font-size: 18px;

  font-weight: 700;



  line-height: 1.4;

}





.erp-section-title::after {



  content: "";



  position: absolute;



  bottom: -1px;



  width: 52px;

  height: 2px;



  border-radius: 20px;



  background: var(--brand-primary);

}





.erp-dashboard-rtl

.erp-section-title::after {



  right: 0;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-section-title::after {



  left: 0;

}





/* =========================================================

   7. PURCHASE CYCLE SECTION

========================================================= */



.erp-purchase-cycle-section {



  margin: 18px 0 24px;

}





.erp-cycle-container {



  position: relative;



  padding: 18px 18px 20px;



  border:

    1px solid var(--brand-border);



  border-radius: 16px;



  /*

     شبه معتم حتى يبقى الـ Pattern ظاهراً بخفة

  */



  background:

    rgba(255, 255, 255, 0.94);



  box-shadow:

    0 5px 18px rgba(36, 59, 99, 0.06);

}





.erp-cycle-title {



  margin-bottom: 20px;

}





/* =========================================================

   SALES / PURCHASE CYCLE GRID

   توزيع البطاقات على كامل عرض الصفحة

========================================================= */



.erp-cycle-grid {

  display: grid;



  grid-template-columns:

    repeat(5, minmax(0, 1fr));



  gap: 18px;



  width: 100%;



  align-items: stretch;

}





.erp-cycle-item {

  position: relative;



  display: flex;



  width: 100%;



  min-width: 0;

}





/* البطاقة تتمدد حسب عرض العمود */

.erp-cycle-card {

  width: 100%;



  min-width: 0;



  min-height: 180px;

}



/* =========================================================

   9. PURCHASE CYCLE CARD

========================================================= */



.erp-cycle-card {



  --cycle-color:

    var(--brand-primary);



  --cycle-soft:

    var(--brand-soft);



  position: relative;



