    800;

}





.erp-modal-summary {



  margin:

    0 0 16px;



  color:

    var(--brand-text) !important;



  font-size:

    13.5px;



  line-height:

    1.75;

}





/* =========================================================

   43. MODAL STEPS BUTTON

========================================================= */



.erp-modal-toggle-steps {



  display: inline-flex;



  align-items: center;



  gap: 6px;



  padding:

    8px 16px;



  border:

    1px solid var(--brand-primary);



  border-radius:

    9px;



  background:

    var(--brand-soft);



  color:

    var(--brand-primary) !important;



  font-family:

    inherit;



  font-size:

    12.5px;



  font-weight:

    700;



  cursor:

    pointer;

}





.erp-modal-toggle-steps:hover {



  background:

    rgba(56, 103, 174, 0.13);

}





/* =========================================================

   44. MODAL STEPS

========================================================= */



.erp-modal-steps {



  max-height: 0;



  overflow: hidden;



  opacity: 0;



  margin-top: 0;



  transition:

    max-height 0.38s ease,

    opacity 0.25s ease,

    margin-top 0.25s ease;

}





.erp-modal-steps.is-shown {



  max-height: 500px;



  opacity: 1;



  margin-top:

    15px;

}





.erp-modal-steps-list {



  margin: 0;



  padding:

    0 20px;



  list-style: none;



  counter-reset:

    step-counter;

}





.erp-modal-steps-list li {



  position: relative;



  counter-increment:

    step-counter;



  padding:

    9px 0;



  border-bottom:

    1px solid rgba(56, 103, 174, 0.10);



  color:

    var(--brand-text) !important;



  font-size:

    12.5px;



  line-height:

    1.65;

}





.erp-modal-steps-list li:last-child {



  border-bottom: 0;

}





.erp-modal-steps-list li::before {



  content:

    counter(step-counter);



  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 22px;

  height: 22px;



  margin-inline-end:

    9px;



  border-radius:

    50%;



  background:

    var(--brand-primary);



  color:

    #ffffff;



  font-size:

    10px;



  font-weight:

    800;

}





/* =========================================================

   45. DARK MODE

========================================================= */



[data-theme="dark"]

.erp-dashboard-wrapper,



html[data-theme="dark"]

.erp-dashboard-wrapper {



  --brand-text:

    #E9EEF7;



  --brand-muted:

    #A7B2C5;



  --brand-border:

    rgba(15, 132, 181, 0.22);



  --brand-border-strong:

    rgba(15, 132, 181, 0.40);

}





/*

   في الوضع الداكن نقلل وضوح Pattern

*/



[data-theme="dark"]

.erp-dashboard-wrapper::before,



html[data-theme="dark"]

.erp-dashboard-wrapper::before {



  opacity: 0.025;

}





[data-theme="dark"]

.erp-cycle-container,



html[data-theme="dark"]

.erp-cycle-container,



[data-theme="dark"]

.erp-overview-container,



html[data-theme="dark"]

.erp-overview-container,



[data-theme="dark"]

.erp-cycle-card,



html[data-theme="dark"]

.erp-cycle-card,



[data-theme="dark"]

.erp-card,



html[data-theme="dark"]

.erp-card,



[data-theme="dark"]

.erp-stat-card,



html[data-theme="dark"]

.erp-stat-card {



  background:

    rgba(32, 36, 44, 0.95);



  box-shadow:

    0 7px 22px rgba(0, 0, 0, 0.18);

}





[data-theme="dark"]

.erp-modal-box,



html[data-theme="dark"]

.erp-modal-box {



  background:

    var(--fg-color, #20242c) !important;

}





/* =========================================================

   46. LARGE TABLET

========================================================= */



@media (max-width: 1250px) {



  .erp-cycle-grid {



    grid-template-columns:

      repeat(4, minmax(0, 1fr));

  }





  .erp-cycle-arrow {



    display: none;

  }





  /*

     نصغر الـ Pattern قليلاً

  */



  .erp-dashboard-wrapper::before {



    -webkit-mask-size:

      155px auto;



    mask-size:

      155px auto;

  }

}





/* =========================================================

   47. TABLET

========================================================= */



@media (max-width: 1050px) {



  .erp-dashboard-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;

  }

}





/* =========================================================

   48. SMALL TABLET

========================================================= */



@media (max-width: 850px) {



  .erp-cycle-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr));

  }





  .erp-overview-container

  .erp-stats-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;

  }





  .erp-quick-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;

  }

}





/* =========================================================

   49. MOBILE

========================================================= */



@media (max-width: 650px) {



  .erp-dashboard-wrapper {



    padding:

      8px 8px 26px;

  }





  /*

     نحافظ على Pattern في الجوال

     لكن نصغره ونخففه

  */



  .erp-dashboard-wrapper::before {



    -webkit-mask-size:

      115px auto;



    mask-size:

      115px auto;



    opacity:

      0.025;

  }





  /* دورة المشتريات */



  .erp-cycle-container {



    padding:

      12px;

  }





  .erp-cycle-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr));



    gap:

      8px;

  }





  .erp-cycle-card {



    min-height:

      155px;



    padding:

      13px 8px;

  }





  .erp-cycle-number {



    width:

      36px;



    height:

      36px;



    flex-basis:

      36px;



    margin-bottom:

      10px;



    font-size:

      15px;

  }





  .erp-cycle-card-title {



    font-size:

      12px;

  }





  .erp-cycle-description {



    font-size:

      9.5px;



    line-height:

      1.55;

  }





  /* نظرة عامة */



  .erp-overview-container {



    padding:

      12px;

  }





  .erp-overview-container

  .erp-stats-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;



    gap:

      9px;

  }





  .erp-stat-card {



    min-height:

      76px;



    padding:

      11px;



    gap:

      8px;

  }





  .erp-stat-icon {



    width:

      36px;



    height:

      36px;



    flex-basis:

      36px;



    font-size:

      9px !important;

  }





  .erp-stat-value,

  .erp-stat-card .erp-stat-value {



    font-size:

      15px !important;

  }





  .erp-stat-label,

  .erp-stat-card .erp-stat-label {



    font-size:

      10px !important;

  }





  /* الاختصارات */



  .erp-quick-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;



    gap:

      8px;

  }





  .erp-quick-btn {



    min-height:

      43px;



    padding:

      9px 7px;



    font-size:

      11.5px;

  }





  /* التقارير */



  .erp-dashboard-grid {



    grid-template-columns:

      1fr !important;



    gap:

      11px;

  }





  .erp-card.is-open {



    transform:

      translateY(-2px);

  }





  /* الفوتر */



  .erp-footer {



    --footer-font-size:

      13px;



    margin-top:

      26px;



    padding-top:

      16px;

  }





  .erp-footer-inner {



    flex-direction:

      column;



    gap:

      8px;

  }





  .erp-footer-item {



    justify-content:

      center;

  }





  .erp-footer-icon {



    font-size:

      15px !important;

  }





  .erp-footer-sep {



    display:

      none;

  }





  /* المودال */



  .erp-modal-overlay {



    align-items:

      flex-end;



    padding:

      10px;

  }





  .erp-modal-box {



    max-height:

      82vh;



    padding:

      22px 17px;



    border-radius:

      16px 16px 0 0;

  }

}

/* =========================================================
   CARDS REMAIN OPEN BY DEFAULT & HOVER-OPEN DISABLED
   إبقاء المربعات مفتوحة بشكل تلقائي وإلغاء الفتح بمرور الماوس
========================================================= */

.erp-card {
  max-height: none !important;
  overflow: visible !important;
  padding-bottom: 15px !important;
}

.erp-card .erp-card-heading {
  margin-bottom: 10px !important;
  border-bottom: 1px solid var(--brand-border) !important;
}

.erp-card .erp-card-chevron {
  transform: rotate(180deg) !important;
}

.erp-card .erp-card-links {
  max-height: none !important;
  overflow: visible !important;
  opacity: 1 !important;
  visibility: visible !important;
  pointer-events: auto !important;
  transform: none !important;
}

script:
(() => {



  /* =========================================================

     MUBTKIR ERP — RECRUITMENT WORKSPACE

  ========================================================= */



  const root =

    root_element.querySelector("[data-erp-dashboard]");



  const cycleSection =

    root_element.querySelector("[data-purchase-cycle]");



  const statsSection =

    root_element.querySelector("[data-stats-section]");



  const quickActions =

    root_element.querySelector("[data-quick-actions]");



  const content =

    root_element.querySelector("[data-dashboard-content]");



  const footerEl =

    root_element.querySelector("[data-dashboard-footer]");



  if (!root) return;





  /* =========================================================

     1. LANGUAGE

  ========================================================= */



  const langValue =

    window.frappe?.boot?.lang ||

    document.documentElement.lang ||

    "en";



  const isArabic =

    String(langValue).toLowerCase().startsWith("ar");



  root.setAttribute(

    "dir",

    isArabic ? "rtl" : "ltr"

  );





  /* =========================================================

     2. HELPERS

  ========================================================= */



  function escapeHtml(value) {



    return String(value ?? "")

      .replace(/&/g, "&amp;")

      .replace(/</g, "&lt;")

      .replace(/>/g, "&gt;")

      .replace(/"/g, "&quot;")

      .replace(/'/g, "&#039;");

  }





  function formatNumber(value) {



    return (

      parseFloat(value) || 0

    ).toLocaleString("en-US");

  }





  function getToday() {



    try {



      if (

        frappe.datetime &&

        frappe.datetime.get_today

      ) {

        return frappe.datetime.get_today();

      }



    } catch (e) {}



    return new Date()

      .toISOString()

      .slice(0, 10);

  }





  function safeCount(doctype, filters = {}) {



    return new Promise(resolve => {



      try {



        frappe.call({



          method: "frappe.client.get_count",



          args: {

            doctype,

            filters

          },



          callback: r => {



            resolve(

              r && r.message

                ? r.message

                : 0

            );



          },



          error: () => resolve(0)



        });



      } catch (e) {



        console.error(

          "Recruitment Count Error:",

          doctype,

          e

        );



        resolve(0);



      }



    });



  }





  function newDoc(doctype) {



    try {



      frappe.new_doc(doctype);



    } catch (e) {



      console.error(

        "Recruitment New Doc Error:",

        doctype,

        e

      );



    }



  }





  /* =========================================================

     3. REPORTS

  ========================================================= */



  const reportNames = new Set([

    "Recruitment Analytics"

  ]);





  function openRoute(name) {



    try {



      if (reportNames.has(name)) {



        frappe.set_route(

          "query-report",

          name

        );



        return;

      }





      frappe.set_route(

        "List",

        name

      );



    } catch (e) {



      console.error(

        "Recruitment Route Error:",

        name,

        e

      );



    }



  }





  /* =========================================================

     4. RECRUITMENT CYCLE

  ========================================================= */



  const cycleCards = [



    {

      step: 1,



      action: "new",

      doctype: "Job Opening",



      labelAr: "إنشاء شاغر وظيفي",

      labelEn: "Job Opening",



      descriptionAr:

        "إنشاء الشاغر وتحديد المسمى الوظيفي وعدد الوظائف المطلوبة.",



      descriptionEn:

        "Create a vacancy and define the position and requirements."

    },





    {

      step: 2,



      action: "route",

      doctype: "Job Applicant",



      labelAr: "استقبال المتقدمين",

      labelEn: "Job Applicants",



      descriptionAr:

        "استقبال وتسجيل طلبات المتقدمين للوظائف.",



      descriptionEn:

        "Receive and manage applications for open positions."

    },





    {

      step: 3,



      action: "new",

      doctype: "Interview",



      labelAr: "المقابلة",

      labelEn: "Interview",



      descriptionAr:

        "تحديد موعد المقابلة وربطها بالمتقدم للوظيفة.",



      descriptionEn:

        "Schedule an interview for the selected applicant."

    },





    {

      step: 4,



      action: "route",

      doctype: "Interview Feedback",



      labelAr: "تقييم المتقدم",

      labelEn: "Interview Feedback",



      descriptionAr:

        "تسجيل تقييم ونتيجة المقابلة للمتقدم.",



      descriptionEn:

        "Record interview feedback and applicant evaluation."

    },





    {

      step: 5,



      action: "new",

      doctype: "Job Offer",



      labelAr: "العرض الوظيفي",

      labelEn: "Job Offer",



      descriptionAr:

        "إصدار العرض الوظيفي للمتقدم المقبول.",



      descriptionEn:

        "Create a job offer for the selected applicant."

    },





    {

      step: 6,



      action: "new",

      doctype: "Employee",



      labelAr: "تحويل إلى موظف",

      labelEn: "Create Employee",



      descriptionAr:

        "إنشاء ملف الموظف بعد قبول العرض الوظيفي.",



      descriptionEn:

        "Create the employee record after accepting the offer."

    }



  ];





  /* =========================================================

     5. OVERVIEW

  ========================================================= */



  const statsCards = [



    {

      id: "open-jobs",



      short: "JOB",



      labelAr: "الشواغر المفتوحة",

      labelEn: "Open Job Openings",



      fetch: () =>

        safeCount(

          "Job Opening",

          {

            status: "Open"

          }

        )

    },





    {

      id: "applicants",



      short: "APP",



      labelAr: "المتقدمون للوظائف",

      labelEn: "Job Applicants",



      fetch: () =>

        safeCount(

          "Job Applicant"

        )

    },





    {

      id: "interviews",



      short: "INT",



      labelAr: "المقابلات القادمة",

      labelEn: "Upcoming Interviews",



      fetch: () =>

        safeCount(

          "Interview",

          {

            scheduled_on: [

              ">=",

              getToday()

            ],

            docstatus: [

              "<",

              2

            ]

          }

        )

    },





    {

      id: "job-offers",



      short: "OFR",



      labelAr: "العروض الوظيفية",

      labelEn: "Job Offers",



      fetch: () =>

        safeCount(

          "Job Offer",

          {

            docstatus: [

              "<",

              2

            ]

          }

        )

    }



  ];





  /* =========================================================

     6. QUICK ACTIONS

  ========================================================= */



  const quickButtons = [



    {

      doctype: "Job Opening",



      labelAr: "شاغر وظيفي جديد",

      labelEn: "New Job Opening"

    },





    {

      doctype: "Job Applicant",



      labelAr: "متقدم جديد",

      labelEn: "New Applicant"

    },





    {

      doctype: "Interview",



      labelAr: "مقابلة جديدة",

      labelEn: "New Interview"

    },





    {

      doctype: "Job Offer",



      labelAr: "عرض وظيفي جديد",

      labelEn: "New Job Offer"

    }



  ];





  /* =========================================================

     7. LOWER CARDS

  ========================================================= */



  const cards = [



    {

      titleAr: "الشواغر الوظيفية",

      titleEn: "Job Openings",



      icon: "💼",



      links: [

        "Job Opening"

      ]

    },





    {

      titleAr: "المتقدمون",

      titleEn: "Applicants",



      icon: "👥",



      links: [

        "Job Applicant"

      ]

    },





    {

      titleAr: "المقابلات",

      titleEn: "Interviews",



      icon: "🗣️",



      links: [

        "Interview",

        "Interview Type",

        "Interview Round",

        "Interview Feedback"

      ]

    },





    {

      titleAr: "العروض الوظيفية",

      titleEn: "Job Offers",



      icon: "📄",



      links: [

        "Job Offer"

      ]

    },





    {

      titleAr: "الموظفون",

      titleEn: "Employees",



      icon: "👤",



      links: [

        "Employee"

      ]

    },





    {

      titleAr: "الهيكل الوظيفي",

      titleEn: "Organization",



      icon: "🏢",



      links: [

        "Department",

        "Designation",

        "Employment Type"

      ]

    },





    {

      titleAr: "إعدادات التوظيف",

      titleEn: "Recruitment Setup",



      icon: "⚙️",



      links: [

        "Staffing Plan",

        "Appointment Letter Template"

      ]

    },





    {

      titleAr: "التقارير",

      titleEn: "Reports",



      icon: "📊",



      links: [

        "Recruitment Analytics"

      ]

    }



  ];





  /* =========================================================

     8. TRANSLATIONS

  ========================================================= */



  const translations = {



    "Job Opening":

      "الشاغر الوظيفي",



    "Job Applicant":

      "المتقدم للوظيفة",



    "Interview":

      "المقابلة",



    "Interview Type":

      "نوع المقابلة",



    "Interview Round":

      "مرحلة المقابلة",



    "Interview Feedback":

      "تقييم المقابلة",



    "Job Offer":

      "العرض الوظيفي",



    "Employee":

      "الموظف",



    "Department":

      "القسم",



    "Designation":

      "المسمى الوظيفي",



    "Employment Type":

      "نوع التوظيف",



    "Staffing Plan":

      "خطة التوظيف",



    "Appointment Letter Template":

      "قالب خطاب التعيين",



    "Recruitment Analytics":

      "تحليل التوظيف"



  };





  function translate(name) {



    if (!isArabic)

      return name;



    return translations[name] || name;

  }





  /* =========================================================

     9. RENDER CYCLE

  ========================================================= */



  function renderCycle() {



    if (!cycleSection)

      return;





    cycleSection.innerHTML = `



      <section class="erp-cycle-container">



        <h2

          class="

            erp-section-title

            erp-cycle-title

          "

        >

          ${

            isArabic

              ? "دورة التوظيف"

              : "Recruitment Cycle"

          }

        </h2>





        <div

          class="erp-cycle-grid"

          style="

            grid-template-columns:

            repeat(

              ${cycleCards.length},

              minmax(0, 1fr)

            );

          "

        >



          ${cycleCards

            .map(

              (card, index) => `



                <div class="erp-cycle-item">



                  <button

                    type="button"

                    class="

                      erp-cycle-card

                      cycle-tone-${(index % 4) + 1}

                    "

                    data-recruit-cycle="${index}"

                  >



                    <span class="erp-cycle-number">

                      ${card.step}

                    </span>





                    <span class="erp-cycle-card-title">



                      ${escapeHtml(

                        isArabic

                          ? card.labelAr

                          : card.labelEn

                      )}



                    </span>





                    <span class="erp-cycle-description">



                      ${escapeHtml(

                        isArabic

                          ? card.descriptionAr

                          : card.descriptionEn

                      )}



                    </span>



                  </button>





                  ${

                    index < cycleCards.length - 1

                      ? `

                        <span class="erp-cycle-arrow">

                          ${isArabic ? "←" : "→"}

                        </span>

                      `

                      : ""

                  }



                </div>



              `

            )

            .join("")}



        </div>



      </section>



    `;





    cycleSection.addEventListener(

      "click",

      event => {



        const element =

          event.target.closest(

            "[data-recruit-cycle]"

          );





        if (!element)

          return;





        const card =

          cycleCards[

            Number(

              element.dataset.recruitCycle

            )

          ];





        if (!card)

          return;





        if (card.action === "new") {



          newDoc(card.doctype);



          return;

        }





        openRoute(card.doctype);



      }

    );



  }





  /* =========================================================

     10. RENDER OVERVIEW

  ========================================================= */



  function renderStats() {



    if (!statsSection)

      return;





    statsSection.innerHTML = `



      <section class="erp-overview-container">



        <h2 class="erp-section-title">



          ${

            isArabic

              ? "نظرة عامة"

              : "Overview"

          }



        </h2>





        <div class="erp-stats-grid">



          ${statsCards

            .map(

              (card, index) => `



                <div

                  class="

                    erp-stat-card

                    overview-tone-${index + 1}

                  "

                >



                  <div class="erp-stat-icon">

                    ${escapeHtml(card.short)}

                  </div>





                  <div class="erp-stat-info">



                    <span

                      class="erp-stat-value"

                      data-recruit-stat="${card.id}"

                    >

                      0

                    </span>





                    <span class="erp-stat-label">



                      ${escapeHtml(

                        isArabic

                          ? card.labelAr

                          : card.labelEn

                      )}



                    </span>



                  </div>



                </div>



              `

            )

            .join("")}



        </div>



      </section>



    `;





    statsCards.forEach(card => {



      Promise

        .resolve()

        .then(() => card.fetch())

        .then(value => {



          const element =

            statsSection.querySelector(

              `[data-recruit-stat="${card.id}"]`

            );





          if (element) {



            element.textContent =

              formatNumber(value);



          }



        })

        .catch(error => {



          console.error(

            "Recruitment Stat Error:",

            card.id,

            error

          );



        });



    });



  }





  /* =========================================================

     11. RENDER QUICK ACTIONS

  ========================================================= */



  function renderQuickActions() {



    if (!quickActions)

      return;





    quickActions.innerHTML = `



      <h2 class="erp-section-title">



        ${

          isArabic

            ? "اختصارات سريعة"

            : "Quick Actions"

        }



      </h2>





      <div class="erp-quick-grid">



        ${quickButtons

          .map(

            (button, index) => `



              <button

                type="button"

                class="erp-quick-btn"

                data-recruit-quick="${index}"

              >



                <span class="erp-quick-label">



                  ${escapeHtml(

                    isArabic

                      ? button.labelAr

                      : button.labelEn

                  )}



                </span>



              </button>



            `

          )

          .join("")}



      </div>



    `;





    quickActions.addEventListener(

      "click",

      event => {



        const element =

          event.target.closest(

            "[data-recruit-quick]"

          );





        if (!element)

          return;





        const button =

          quickButtons[

            Number(

              element.dataset.recruitQuick

            )

          ];





        if (!button)

          return;





        newDoc(button.doctype);



      }

    );



  }





  /* =========================================================

     12. RENDER LOWER CARDS

  ========================================================= */



  function renderCards() {



    if (!content)

      return;





    const cardsHtml =

      cards

        .map(

          (card, index) => {



            const links =

              card.links

                .map(

                  item => `



                    <div class="erp-link-row">



                      <button

                        type="button"

                        class="erp-link"

                        data-recruit-route="${escapeHtml(item)}"

                      >



                        <span class="erp-link-text">

                          ${escapeHtml(translate(item))}

                        </span>





                        <span class="erp-link-arrow">

                          ${isArabic ? "←" : "→"}

                        </span>



                      </button>



                    </div>



                  `

                )

                .join("");





            return `



              <article

                class="

                  erp-card

                  tone-${index % 5}

                "

                data-recruit-card

              >



                <button

                  type="button"

                  class="erp-card-heading"

                  data-recruit-toggle

                  aria-expanded="false"

                >



                  <span class="erp-icon">

                    ${card.icon}

                  </span>





                  <span class="erp-card-title">



                    ${escapeHtml(

                      isArabic

                        ? card.titleAr

                        : card.titleEn

                    )}



                  </span>





                  <span class="erp-card-chevron">

                    ⌄

                  </span>



                </button>





                <div class="erp-card-links">

                  ${links}

                </div>



              </article>



            `;



          }

        )

        .join("");





    content.innerHTML = `



      <section class="erp-module-section">



        <h2 class="erp-section-title">



          ${

            isArabic

              ? "البيانات الرئيسية والتقارير"

              : "Reports & Masters"

          }



        </h2>





        <div class="erp-dashboard-grid">

          ${cardsHtml}

        </div>



      </section>



    `;





    content.addEventListener(

      "click",

      event => {





        const routeButton =

          event.target.closest(

            "[data-recruit-route]"

          );





        if (routeButton) {



          event.preventDefault();



          openRoute(

            routeButton.dataset.recruitRoute

          );



          return;

        }





        const toggle =

          event.target.closest(

            "[data-recruit-toggle]"

          );





        if (!toggle)

          return;





        const selectedCard =

          toggle.closest(

            "[data-recruit-card]"

          );





        if (!selectedCard)

          return;





        const shouldOpen =

          !selectedCard.classList.contains(

            "is-open"

          );





        content

          .querySelectorAll(

            "[data-recruit-card]"

          )

          .forEach(card => {



            if (card !== selectedCard) {



              card.classList.remove(

                "is-open"

              );



            }



          });





        selectedCard.classList.toggle(

          "is-open",

          shouldOpen

        );



      }

    );



  }





  /* =========================================================

     13. FOOTER

  ========================================================= */



  function renderFooter() {



    if (!footerEl)

      return;





    footerEl.innerHTML = `



      <div class="erp-footer-inner">



        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ☎

          </span>



          <span class="erp-footer-label">



            ${

              isArabic

                ? "الهاتف الموحد:"

                : "Phone:"

            }



          </span>



          <a

            href="tel:0115110455"

            class="erp-footer-link"

            dir="ltr"

          >

            0115110455

          </a>



        </div>





        <span class="erp-footer-sep">

          |

        </span>





        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ✉

          </span>



          <span class="erp-footer-label">



            ${

              isArabic

                ? "البريد الإلكتروني:"

                : "Email:"

            }



          </span>



          <a

            href="mailto:sales@mubtkir.com"

            class="erp-footer-link"

          >

            sales@mubtkir.com

          </a>



        </div>





        <span class="erp-footer-sep">

          |

        </span>





        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ◎

          </span>



          <span class="erp-footer-label">



            ${

              isArabic

                ? "الموقع:"

                : "Website:"

            }



          </span>



          <a

            href="https://www.mubtkir.com"

            class="erp-footer-link"

            target="_blank"

            rel="noopener"

          >

            www.mubtkir.com

          </a>



        </div>



      </div>



    `;



  }





  /* =========================================================

     14. INIT

  ========================================================= */



  try {



    renderCycle();



  } catch (e) {



    console.error(

      "Recruitment Cycle Error:",

      e

    );



  }





  try {



    renderStats();



  } catch (e) {



    console.error(

      "Recruitment Stats Error:",

      e

    );



  }





  try {



    renderQuickActions();



  } catch (e) {



    console.error(

      "Recruitment Quick Actions Error:",

      e

    );



  }





  try {



    renderCards();



  } catch (e) {



    console.error(

      "Recruitment Cards Error:",

      e

    );



  }





  try {



    renderFooter();



  } catch (e) {



    console.error(

      "Recruitment Footer Error:",

      e

    );



  }



})();

