script:
(() => {



  /* =========================================================

     MUBTKIR ERP — LEAVES WORKSPACE

     لوحة تحكم الإجازات

  ========================================================= */



  const root =

    root_element.querySelector("[data-erp-dashboard]");



  const cycleSection =

    root_element.querySelector("[data-purchase-cycle]");



  const statsSection =

    root_element.querySelector("[data-stats-section]");



  const quickActions =

    root_element.querySelector("[data-quick-actions]");



  const content =

    root_element.querySelector("[data-dashboard-content]");



  const footerEl =

    root_element.querySelector("[data-dashboard-footer]");



  if (!root) return;





  /* =========================================================

     1. LANGUAGE

  ========================================================= */



  const langValue =

    window.frappe?.boot?.lang ||

    document.documentElement.lang ||

    "en";



  const isArabic =

    String(langValue)

      .toLowerCase()

      .startsWith("ar");



  root.setAttribute(

    "dir",

    isArabic ? "rtl" : "ltr"

  );





  /* =========================================================

     2. HELPERS

  ========================================================= */



  function escapeHtml(value) {



    return String(value ?? "")

      .replace(/&/g, "&amp;")

      .replace(/</g, "&lt;")

      .replace(/>/g, "&gt;")

      .replace(/"/g, "&quot;")

      .replace(/'/g, "&#039;");

  }





  function formatNumber(value) {



    return (

      parseFloat(value) || 0

    ).toLocaleString("en-US");

  }





  function getToday() {



    try {



      if (

        frappe.datetime &&

        frappe.datetime.get_today

      ) {

        return frappe.datetime.get_today();

      }



    } catch (e) {}



    return new Date()

      .toISOString()

      .slice(0, 10);

  }





  function getMonthStart() {



    const d = new Date();



    const year =

      d.getFullYear();



    const month =

      String(

        d.getMonth() + 1

      ).padStart(2, "0");



    return `${year}-${month}-01`;

  }





