          args: {

            doctype,

            filters

          },



          callback: r => {



            resolve(

              r?.message || 0

            );



          },



          error: () =>

            resolve(0)



        });



      } catch (e) {



        console.error(

          "Leaves Count Error:",

          doctype,

          e

        );



        resolve(0);



      }



    });



  }





