  function renderCycle() {



    if (!cycleSection)

      return;





    cycleSection.innerHTML = `



      <section class="erp-cycle-container">



        <h2

          class="

            erp-section-title

            erp-cycle-title

          "

        >

          ${

            isArabic

              ? "دورة الإجازات"

              : "Leave Management Cycle"

          }

        </h2>





        <div

          class="erp-cycle-grid"

          style="

            grid-template-columns:

            repeat(

              ${cycleCards.length},

              minmax(0,1fr)

            );

          "

        >



          ${cycleCards

            .map(

              (card, index) => `



                <div class="erp-cycle-item">



                  <button

                    type="button"

                    class="

                      erp-cycle-card

                      cycle-tone-${(index % 4) + 1}

                    "

                    data-leave-cycle="${index}"

                  >



                    <span

                      class="erp-cycle-number"

                    >

                      ${card.step}

                    </span>





                    <span

                      class="erp-cycle-card-title"

                    >

                      ${escapeHtml(

                        isArabic

                          ? card.labelAr

                          : card.labelEn

                      )}

                    </span>





                    <span

                      class="erp-cycle-description"

                    >

                      ${escapeHtml(

                        isArabic

                          ? card.descriptionAr

                          : card.descriptionEn

                      )}

                    </span>



                  </button>





                  ${

                    index <

                    cycleCards.length - 1



                      ? `

                        <span

                          class="erp-cycle-arrow"

                        >

                          ${isArabic ? "←" : "→"}

                        </span>

                      `



                      : ""

                  }



