    cycleSection.addEventListener(

      "click",

      event => {



        const element =

          event.target.closest(

            "[data-leave-cycle]"

          );





        if (!element)

          return;





        const card =

          cycleCards[

            Number(

              element.dataset.leaveCycle

            )

