          openRoute(

            routeButton.dataset.leaveRoute

          );



          return;



        }





        const toggle =

          event.target.closest(

            "[data-leave-toggle]"

          );





        if (!toggle)

          return;





        const selectedCard =

          toggle.closest(

            "[data-leave-card]"

          );





        if (!selectedCard)

          return;





        const shouldOpen =

          !selectedCard.classList.contains(

            "is-open"

          );





        content

          .querySelectorAll(

            "[data-leave-card]"

          )

          .forEach(

            card => {



              if (

                card !== selectedCard

              ) {



                card.classList.remove(

                  "is-open"

                );



              }



            }

          );





        selectedCard

          .classList

          .toggle(

            "is-open",

            shouldOpen

          );



      }

    );



  }





