    root_element.querySelector("[data-dashboard-content]");



  const footerEl =

    root_element.querySelector("[data-dashboard-footer]");



  if (!root) return;





  /* =========================================================

     1. LANGUAGE

  ========================================================= */



  const langValue =

    window.frappe?.boot?.lang ||

    document.documentElement.lang ||

    "en";



  const isArabic =

    String(langValue)

      .toLowerCase()

      .startsWith("ar");



  root.setAttribute(

    "dir",

    isArabic ? "rtl" : "ltr"

  );





  /* =========================================================

     2. HELPERS

  ========================================================= */



  function escapeHtml(value) {



    return String(value ?? "")

      .replace(/&/g, "&amp;")

      .replace(/</g, "&lt;")

      .replace(/>/g, "&gt;")

      .replace(/"/g, "&quot;")

      .replace(/'/g, "&#039;");

  }





  function formatNumber(value) {



    return (

      parseFloat(value) || 0

    ).toLocaleString("en-US");

  }





  function getMonthStart() {



    const d = new Date();



    const year =

      d.getFullYear();



    const month =

      String(

        d.getMonth() + 1

      ).padStart(2, "0");



    return `${year}-${month}-01`;

  }





  function safeCount(

    doctype,

    filters = {}

  ) {



    return new Promise(resolve => {



      try {



        frappe.call({



          method:

            "frappe.client.get_count",



          args: {

            doctype,

            filters

          },



          callback: r => {



            resolve(

              r?.message || 0

            );



          },



          error: () =>

            resolve(0)



        });



      } catch (e) {



        console.error(

          "Expense Claim Count Error:",

          doctype,

          e

        );



        resolve(0);



      }



    });



  }





  function newDoc(doctype) {



    try {



      frappe.new_doc(

        doctype

      );



    } catch (e) {



      console.error(

        "Expense Claim New Doc Error:",

        doctype,

        e

