                      cycle-tone-${(index % 4) + 1}

                    "

                    data-lifecycle-cycle="${index}"

                  >



                    <span

                      class="erp-cycle-number"

                    >

                      ${card.step}

                    </span>





                    <span

                      class="erp-cycle-card-title"

                    >



                      ${escapeHtml(

                        isArabic

                          ? card.labelAr

                          : card.labelEn

                      )}



                    </span>





                    <span

                      class="erp-cycle-description"

                    >



                      ${escapeHtml(

                        isArabic

                          ? card.descriptionAr

                          : card.descriptionEn

                      )}



                    </span>



                  </button>





                  ${

                    index <

                    cycleCards.length - 1



                      ? `

                        <span class="erp-cycle-arrow">

                          ${isArabic ? "←" : "→"}

                        </span>

                      `



                      : ""

                  }



                </div>



              `

            )

            .join("")}



        </div>



      </section>



    `;





    cycleSection.addEventListener(

      "click",

      event => {



        const element =

          event.target.closest(

            "[data-lifecycle-cycle]"

          );





        if (!element)

          return;





        const card =

          cycleCards[

            Number(

              element.dataset.lifecycleCycle

            )

          ];





        if (!card)

          return;





        if (

          card.action === "new"

        ) {



          newDoc(

            card.doctype

          );



          return;

        }





        if (

          card.action ===

          "movement-selector"

        ) {



          showMovementSelector();



          return;

        }





        openRoute(

          card.doctype

        );



      }

    );



  }





  /* =========================================================

     11. RENDER STATS

  ========================================================= */



  function renderStats() {



    if (!statsSection)

      return;





    statsSection.innerHTML = `



      <section class="erp-overview-container">



        <h2 class="erp-section-title">



          ${

            isArabic

              ? "نظرة عامة"

              : "Overview"

          }



        </h2>





        <div class="erp-stats-grid">



          ${statsCards

            .map(

              (card, index) => `



                <div

                  class="

                    erp-stat-card

                    overview-tone-${index + 1}

                  "

                >



                  <div class="erp-stat-icon">

                    ${escapeHtml(card.short)}

                  </div>





                  <div class="erp-stat-info">



                    <span

                      class="erp-stat-value"

                      data-lifecycle-stat="${card.id}"

                    >

                      0

                    </span>





                    <span

                      class="erp-stat-label"

                    >



                      ${escapeHtml(

                        isArabic

                          ? card.labelAr

                          : card.labelEn

                      )}



                    </span>



                  </div>



                </div>



              `

            )

            .join("")}



        </div>



      </section>



    `;





    statsCards.forEach(

      card => {



        Promise

          .resolve()

          .then(

            () => card.fetch()

          )

          .then(

            value => {



              const element =

                statsSection.querySelector(

                  `[data-lifecycle-stat="${card.id}"]`

                );





              if (element) {



                element.textContent =

                  formatNumber(value);



              }



            }

          )

          .catch(

            error => {



              console.error(

                "Lifecycle Stat Error:",

                card.id,

                error

              );



            }

          );



      }

    );



  }





  /* =========================================================

     12. QUICK ACTIONS

  ========================================================= */



  function renderQuickActions() {



    if (!quickActions)

      return;





    quickActions.innerHTML = `



      <h2 class="erp-section-title">



        ${

          isArabic

            ? "اختصارات سريعة"

            : "Quick Actions"

        }



      </h2>





      <div class="erp-quick-grid">



        ${quickButtons

          .map(

            (button, index) => `



              <button

                type="button"

                class="erp-quick-btn"

                data-lifecycle-quick="${index}"

              >



                <span

                  class="erp-quick-label"

                >



                  ${escapeHtml(

                    isArabic

                      ? button.labelAr

                      : button.labelEn

                  )}



                </span>



              </button>



            `

          )

          .join("")}



      </div>



    `;





    quickActions.addEventListener(

      "click",

      event => {



        const element =

          event.target.closest(

            "[data-lifecycle-quick]"

          );





        if (!element)

          return;





        const button =

          quickButtons[

            Number(

              element.dataset.lifecycleQuick

            )

          ];





        if (!button)

          return;





        newDoc(

          button.doctype

        );



      }

    );



  }





  /* =========================================================

     13. RENDER CARDS

  ========================================================= */



  function renderCards() {



    if (!content)

      return;





    const cardsHtml =

      cards

        .map(

          (card, index) => {



            const links =

              card.links

                .map(

                  item => `



                    <div class="erp-link-row">



                      <button

                        type="button"

                        class="erp-link"

                        data-lifecycle-route="${escapeHtml(item)}"

                      >



                        <span class="erp-link-text">

                          ${escapeHtml(translate(item))}

                        </span>





                        <span class="erp-link-arrow">

                          ${isArabic ? "←" : "→"}

                        </span>



                      </button>



                    </div>



                  `

                )

                .join("");





            return `



              <article

                class="

                  erp-card

                  tone-${index % 5}

                "

                data-lifecycle-card

              >



                <button

                  type="button"

                  class="erp-card-heading"

                  data-lifecycle-toggle

                  aria-expanded="false"

                >



                  <span class="erp-icon">

                    ${card.icon}

                  </span>





                  <span

                    class="erp-card-title"

                  >



                    ${escapeHtml(

                      isArabic

                        ? card.titleAr

                        : card.titleEn

                    )}



                  </span>





                  <span

                    class="erp-card-chevron"

                  >

                    ⌄

                  </span>



                </button>





                <div class="erp-card-links">

                  ${links}

                </div>



              </article>



            `;



          }

        )

        .join("");





    content.innerHTML = `



      <section class="erp-module-section">



        <h2 class="erp-section-title">



          ${

            isArabic

              ? "البيانات الرئيسية"

              : "Masters & Operations"

          }



        </h2>





        <div class="erp-dashboard-grid">

          ${cardsHtml}

        </div>



      </section>



    `;





    content.addEventListener(

      "click",

      event => {



        const routeButton =

          event.target.closest(

            "[data-lifecycle-route]"

          );





        if (routeButton) {



          event.preventDefault();



          openRoute(

            routeButton.dataset.lifecycleRoute

          );



          return;

        }





        const toggle =

          event.target.closest(

            "[data-lifecycle-toggle]"

          );





        if (!toggle)

          return;





        const selectedCard =

          toggle.closest(

            "[data-lifecycle-card]"

          );





        if (!selectedCard)

          return;





        const shouldOpen =

          !selectedCard.classList.contains(

            "is-open"

          );





        content

          .querySelectorAll(

            "[data-lifecycle-card]"

          )

          .forEach(card => {



            if (

              card !== selectedCard

            ) {



              card.classList.remove(

                "is-open"

              );



            }



          });





        selectedCard.classList.toggle(

          "is-open",

          shouldOpen

        );



      }

    );



  }





  /* =========================================================

     14. FOOTER

  ========================================================= */



  function renderFooter() {



    if (!footerEl)

      return;





    footerEl.innerHTML = `



      <div class="erp-footer-inner">



        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ☎

          </span>



          <span class="erp-footer-label">

            ${

              isArabic

                ? "الهاتف الموحد:"

                : "Phone:"

            }

          </span>



          <a

            href="tel:0115110455"

            class="erp-footer-link"

            dir="ltr"

          >

            0115110455

          </a>



        </div>





        <span class="erp-footer-sep">

          |

        </span>





        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ✉

          </span>



          <span class="erp-footer-label">

            ${

              isArabic

                ? "البريد الإلكتروني:"

                : "Email:"

            }

          </span>



          <a

            href="mailto:sales@mubtkir.com"

            class="erp-footer-link"

          >

            sales@mubtkir.com

          </a>



        </div>





        <span class="erp-footer-sep">

          |

        </span>





        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ◎

          </span>



          <span class="erp-footer-label">

            ${

              isArabic

                ? "الموقع:"

                : "Website:"

            }

          </span>



          <a

            href="https://www.mubtkir.com"

            class="erp-footer-link"

            target="_blank"

            rel="noopener"

          >

            www.mubtkir.com

          </a>



        </div>



      </div>



    `;



  }





  /* =========================================================

     15. INIT

  ========================================================= */



  try {

    renderCycle();

  } catch (e) {

    console.error(

      "Lifecycle Cycle Error:",

      e

    );

  }





  try {

    renderStats();

  } catch (e) {

    console.error(

      "Lifecycle Stats Error:",

      e

    );

  }





  try {

    renderQuickActions();

  } catch (e) {

    console.error(

      "Lifecycle Quick Actions Error:",

      e

    );

  }





  try {

    renderCards();

  } catch (e) {

    console.error(

      "Lifecycle Cards Error:",

      e

    );

  }





  try {

    renderFooter();

  } catch (e) {

    console.error(

      "Lifecycle Footer Error:",

      e

    );

  }



})();

style:
/* =========================================================

   MUBTKIR ERP — BUYING WORKSPACE

   Unified Professional Brand Theme

   لوحة تحكم قسم المشتريات

========================================================= */





/* =========================================================

   1. ROOT + BRAND COLORS

   ألوان الهوية الرسمية

========================================================= */



.erp-dashboard-wrapper {



  --brand-primary: #3867AE;

  --brand-secondary: #0F84B5;

  --brand-accent: #0BA1B8;

  --brand-purple: #644DA6;



  --brand-text: #243B63;

  --brand-muted: #66758A;



  --brand-border: rgba(56, 103, 174, 0.22);

  --brand-border-strong: rgba(56, 103, 174, 0.38);



  --brand-soft: rgba(56, 103, 174, 0.07);

  --brand-soft-secondary: rgba(15, 132, 181, 0.07);

  --brand-soft-accent: rgba(11, 161, 184, 0.07);

  --brand-soft-purple: rgba(100, 77, 166, 0.07);



  position: relative;

  isolation: isolate;



  width: 100%;



  padding: 14px 16px 36px;



  overflow: visible;



  color: var(--brand-text);

}





/* =========================================================

   2. FONT

========================================================= */



.erp-dashboard-wrapper,

.erp-dashboard-wrapper * {



  box-sizing: border-box;



  font-family:

    "Tajawal",

    "Inter",

    Arial,

    sans-serif !important;

}





/* =========================================================

   3. RTL

========================================================= */



.erp-dashboard-wrapper.erp-dashboard-rtl {



  direction: rtl;

  text-align: right;

}





/* =========================================================

   BACKGROUND

   صورة واحدة في الخلفية بدون تكرار

========================================================= */



.erp-dashboard-bg {

    position: absolute !important;



    top: 50px;

    left: 50%;



    /* حجم الصورة */

    width: 78%;

    max-width: 1200px;



    height: auto;



    transform: translateX(-50%);



    /* الشفافية */

    opacity: 0.03;



    object-fit: contain;



    pointer-events: none;

    user-select: none;



    z-index: 0;

}





/* الحاوية الرئيسية */

.erp-dashboard-wrapper {

    position: relative !important;

    isolation: isolate;

}





/* المحتوى فوق الخلفية */

.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {

    position: relative !important;

    z-index: 2;

}



/* =========================================================

   المحتوى فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {



    position: relative;



    z-index: 2;

}

/* =========================================================

   إبقاء جميع عناصر الداشبورد فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {

    position: relative;

    z-index: 2;

}



/* =========================================================

   5. CONTENT LAYER

   جميع المحتويات تظهر فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {



  position: relative;



  z-index: 2;

}





.erp-dashboard-content,

.erp-module-section,

.erp-dashboard-grid {



  background: transparent !important;

}





/* =========================================================

   6. SECTION TITLE

========================================================= */



.erp-section-title {



  position: relative;



  display: flex;

  align-items: center;



  min-height: 36px;



  margin: 0 0 16px;



  padding: 0 0 10px;



  border-bottom:

    1px solid var(--brand-border);



  color:

    var(--brand-text) !important;



  font-size: 18px;

  font-weight: 700;



  line-height: 1.4;

}





.erp-section-title::after {



  content: "";



  position: absolute;



  bottom: -1px;



  width: 52px;

  height: 2px;



  border-radius: 20px;



  background: var(--brand-primary);

}





.erp-dashboard-rtl

.erp-section-title::after {



  right: 0;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-section-title::after {



  left: 0;

}





/* =========================================================

   7. PURCHASE CYCLE SECTION

========================================================= */



.erp-purchase-cycle-section {



  margin: 18px 0 24px;

}





.erp-cycle-container {



  position: relative;



  padding: 18px 18px 20px;



  border:

    1px solid var(--brand-border);



  border-radius: 16px;



  /*

     شبه معتم حتى يبقى الـ Pattern ظاهراً بخفة

  */



  background:

    rgba(255, 255, 255, 0.94);



  box-shadow:

    0 5px 18px rgba(36, 59, 99, 0.06);

}





.erp-cycle-title {



  margin-bottom: 20px;

}





/* =========================================================

   SALES / PURCHASE CYCLE GRID

   توزيع البطاقات على كامل عرض الصفحة

========================================================= */



.erp-cycle-grid {

  display: grid;



  grid-template-columns:

    repeat(5, minmax(0, 1fr));



  gap: 18px;



  width: 100%;



  align-items: stretch;

}





.erp-cycle-item {

  position: relative;



  display: flex;



  width: 100%;



  min-width: 0;

}





/* البطاقة تتمدد حسب عرض العمود */

.erp-cycle-card {

  width: 100%;



  min-width: 0;



  min-height: 180px;

}



/* =========================================================

   9. PURCHASE CYCLE CARD

========================================================= */



.erp-cycle-card {



  --cycle-color:

    var(--brand-primary);



  --cycle-soft:

    var(--brand-soft);



  position: relative;



  display: flex;



  flex-direction: column;



  align-items: center;

  justify-content: flex-start;



  width: 100%;



  min-width: 0;

  min-height: 180px;



  padding: 17px 11px 15px;



  overflow: hidden;



  border:

    1px solid var(--brand-border);



  border-radius: 14px;



  outline: none;



  background:

    rgba(255, 255, 255, 0.96);



  color:

    var(--brand-text) !important;



  font-family: inherit;



  text-align: center;



  cursor: pointer;



  transition:

    transform 0.20s ease,

    border-color 0.20s ease,

    box-shadow 0.20s ease;

}





.erp-cycle-card::before {



  content: "";



  position: absolute;



  inset: 0;



  border-radius: inherit;



  background:

    var(--cycle-soft);



  opacity: 0.42;



  pointer-events: none;

}





.erp-cycle-card::after {



  content: "";



  position: absolute;



  right: 0;

  bottom: 0;



  width: 0;

  height: 3px;



  background:

    var(--cycle-color);



  transition:

    width 0.25s ease;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-cycle-card::after {



  right: auto;

  left: 0;

}





.erp-cycle-card > * {



  position: relative;



  z-index: 2;

}





@media (hover: hover) {



  .erp-cycle-card:hover {



    transform:

      translateY(-4px);



    border-color:

      var(--cycle-color);



    box-shadow:

      0 12px 28px rgba(36, 59, 99, 0.12);

  }





  .erp-cycle-card:hover::after {



    width: 100%;

  }

}





/* =========================================================

   10. CYCLE NUMBER

========================================================= */



.erp-cycle-number {



  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 42px;

  height: 42px;



  flex: 0 0 42px;



  margin-bottom: 14px;



  border-radius: 50%;



  background:

    var(--cycle-color);



  color:

    #ffffff !important;



  font-size: 18px;

  font-weight: 800;



  line-height: 1;



  box-shadow:

    0 5px 14px rgba(36, 59, 99, 0.12);

}





/* =========================================================

   11. CYCLE TITLE

========================================================= */



.erp-cycle-card-title {



  display: block;



  width: 100%;



  margin-bottom: 7px;



  color:

    var(--brand-text) !important;



  font-size: 13.5px;

  font-weight: 800;



  line-height: 1.45;

}





/* =========================================================

   12. CYCLE DESCRIPTION

========================================================= */



.erp-cycle-description {



  display: block;



  width: 100%;



  color:

    var(--brand-muted) !important;



  font-size: 10.5px;

  font-weight: 500;



  line-height: 1.65;

}





/* =========================================================

   13. CYCLE BRAND COLORS

========================================================= */



.erp-cycle-card.cycle-tone-1 {



  --cycle-color:

    var(--brand-primary);



  --cycle-soft:

    var(--brand-soft);

}





.erp-cycle-card.cycle-tone-2 {



  --cycle-color:

    var(--brand-secondary);



  --cycle-soft:

    var(--brand-soft-secondary);

}





.erp-cycle-card.cycle-tone-3 {



  --cycle-color:

    var(--brand-accent);



  --cycle-soft:

    var(--brand-soft-accent);

}





.erp-cycle-card.cycle-tone-4 {



  --cycle-color:

    var(--brand-purple);



  --cycle-soft:

    var(--brand-soft-purple);

}





/* =========================================================

   14. CYCLE ARROW

========================================================= */



.erp-cycle-arrow {



  position: absolute;



  top: 50%;



  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 20px;

  height: 20px;



  color:

