@media (hover: hover) {



  .erp-stat-card:hover {



    transform:

      translateY(-3px);



    border-color:

      var(--brand-border-strong);



    box-shadow:

      0 10px 26px rgba(36, 59, 99, 0.10);

  }

}





/* =========================================================

   18. STAT ICON

========================================================= */



.erp-stat-icon {



  display: flex;



  align-items: center;

  justify-content: center;



  width: 46px;

  height: 46px;



  flex: 0 0 46px;



  border-radius: 12px;



  background:

    var(--brand-soft);



  color:

    var(--brand-primary) !important;



  font-size: 11px !important;

  font-weight: 800;



  letter-spacing: 0.4px;

}





.erp-stat-card.overview-tone-1

.erp-stat-icon {



  background:

    var(--brand-soft);



  color:

    var(--brand-primary) !important;

}





.erp-stat-card.overview-tone-2

.erp-stat-icon {



  background:

    var(--brand-soft-secondary);



  color:

    var(--brand-secondary) !important;

}





.erp-stat-card.overview-tone-3

.erp-stat-icon {



  background:

    var(--brand-soft-accent);



  color:

    var(--brand-accent) !important;

}





.erp-stat-card.overview-tone-4

.erp-stat-icon {



  background:

    var(--brand-soft-purple);



  color:

    var(--brand-purple) !important;

}





/* =========================================================

   19. STAT INFO

========================================================= */



.erp-stat-info {



  display: flex;



  flex-direction: column;



  gap: 3px;



  min-width: 0;



  color:

    var(--brand-text) !important;

}





.erp-stat-value,

.erp-stat-card .erp-stat-value {



  color:

    var(--brand-text) !important;



  font-size:

    20px !important;



  font-weight:

    800 !important;



  line-height: 1.3;



  direction: ltr;

}





.erp-stat-label,

.erp-stat-card .erp-stat-label {



  color:

    var(--brand-text) !important;



  font-size:

    12px !important;



  font-weight:

    600 !important;



  line-height: 1.45;

}





/* =========================================================

   20. QUICK ACTIONS

   تم إبقاء تصميم الاختصارات كما كان

========================================================= */



.erp-quick-actions {



  margin-bottom: 24px;

}





/* =========================================================

