      stepsAr: [
        "اضغط «تحويل أسهم جديد»",
        "اختر نوع المعاملة (إصدار جديد، تحويل، استرداد)",
        "حدد المساهم المحول والمساهم المستلم",
        "أدخل عدد الأسهم والقيمة الاسمية وفئة الأسهم",
        "حدد حسابات الدفع الناتجة عن العملية",
