        "Select source shareholder and target shareholder",
        "Enter number of shares, face value, and share type",
        "Set payment and equity accounts",
        "Click «Save» then «Submit»"
      ]
    }
  };

  /* ─────────────────────────────────────────
     ٨. دوال مساعدة
  ───────────────────────────────────────── */

  function translate(name) {
    if (!isArabic) return name;
    if (arabicFallback[name]) return arabicFallback[name];
    if (typeof window.__ === "function") return window.__(name);
    return name;
  }

  function escapeHtml(value) {
    return String(value ?? "")
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#039;");
  }

  function formatNumber(num) {
    const n = parseFloat(num) || 0;
    if (n % 1 !== 0) {
      return n.toLocaleString("en-US", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
      });
    }
    return n.toLocaleString("en-US");
  }

  /* ─────────────────────────────────────────
     ٩. نافذة التفاصيل المنبثقة
  ───────────────────────────────────────── */

  function showInfoModal(itemName) {
    const desc = itemDescriptions[itemName];
    const title = isArabic ? (translate(itemName) || itemName) : itemName;
    const summary = desc
      ? (isArabic ? desc.summaryAr : desc.summaryEn)
      : (isArabic ? ("إدارة ومتابعة " + title + " وتنفيذ العمليات المرتبطة بها.") : ("Manage and track " + itemName + "."));
    const rawSteps = desc ? (isArabic ? desc.stepsAr : desc.stepsEn) : null;
    const steps = (Array.isArray(rawSteps) && rawSteps.length > 0)
      ? rawSteps
      : (isArabic
          ? [
              "فتح شاشة " + title,
              "إدخال وتعبئة البيانات الأساسية المطلوبة",
              "مراجعة وتدقيق الحقول والتحقق من صحتها",
              "حفظ السجل واعتماد المستند"
            ]
          : [
              "Open " + itemName,
              "Fill in the required information and fields",
              "Review and verify mandatory values",
              "Save and submit the record"
            ]);

    // إزالة أي نافذة سابقة مفتوحة
    const existing = root.querySelector(".erp-modal-overlay") || document.querySelector(".erp-modal-overlay");
    if (existing) existing.remove();

    const overlay = document.createElement("div");
    overlay.className = "erp-modal-overlay";
    overlay.setAttribute("dir", isArabic ? "rtl" : "ltr");

    overlay.innerHTML = `
      <div class="erp-modal-box">
        <button type="button" class="erp-modal-close" data-modal-close aria-label="${isArabic ? "إغلاق" : "Close"}">✕</button>
        <div class="erp-modal-header">
          <span class="erp-modal-icon">${desc?.icon || "📄"}</span>
          <h3 class="erp-modal-title">${escapeHtml(title)}</h3>
        </div>
        <p class="erp-modal-summary">${escapeHtml(summary)}</p>

        <div class="erp-modal-steps is-shown" data-modal-steps>
          <ol class="erp-modal-steps-list">
            ${steps.map(s => `<li>${escapeHtml(s)}</li>`).join("")}
          </ol>
        </div>

        <div style="margin-top: 18px;">
          <button
            type="button"
            class="erp-quick-btn"
            data-modal-launch
            style="width: 100%; min-height: 42px;"
          >
            <span class="erp-quick-label">${isArabic ? "فتح الشاشة" : "Open Screen"}</span>
          </button>
        </div>
      </div>
    `;

    root.appendChild(overlay);
    setTimeout(() => overlay.classList.add("is-visible"), 10);

    const closeModal = () => {
      overlay.classList.remove("is-visible");
      setTimeout(() => overlay.remove(), 280);
    };

    const closeBtn = overlay.querySelector("[data-modal-close]");
    if (closeBtn) closeBtn.addEventListener("click", closeModal);

    overlay.addEventListener("click", e => {
      if (e.target === overlay) closeModal();
    });

    const launchBtn = overlay.querySelector("[data-modal-launch]");
    if (launchBtn) {
      launchBtn.addEventListener("click", () => {
        closeModal();
        openRoute(itemName);
      });
    }
  }

  /* ─────────────────────────────────────────
     ١٠. إنشاء بطاقات الإحصائيات
  ───────────────────────────────────────── */

  function renderStats() {
    if (!statsSection) return;

    statsSection.innerHTML = `
      <div class="erp-stats-grid">
        ${statsCards.map(c => `
          <div class="erp-stat-card" data-stat-id="${escapeHtml(c.id)}">
            <div class="erp-stat-badge">${escapeHtml(c.short)}</div>
            <div class="erp-stat-info">
              <span class="erp-stat-label">${escapeHtml(isArabic ? c.labelAr : c.labelEn)}</span>
              <span class="erp-stat-value" data-stat-value>—</span>
            </div>
          </div>
        `).join("")}
      </div>
    `;

    statsCards.forEach(c => {
      c.fetch().then(val => {
        const el = statsSection.querySelector(`[data-stat-id="${c.id}"] [data-stat-value]`);
        if (el) {
          el.textContent = c.isCurrency ? `${formatNumber(val)} SAR` : formatNumber(val);
        }
      });
    });
  }

  /* ─────────────────────────────────────────
     ١١. إنشاء أزرار الاختصارات السريعة
  ───────────────────────────────────────── */

  function renderQuickActions() {
    if (!quickActions) return;

    const title = isArabic ? "اختصارات سريعة" : "Quick Actions";

    quickActions.innerHTML = `
      <h2 class="erp-section-title">${escapeHtml(title)}</h2>
      <div class="erp-quick-grid">
        ${quickActionButtons.map(btn => {
          const label = isArabic ? btn.labelAr : btn.labelEn;
          return `
            <button type="button" class="erp-quick-btn" data-new-doc="${escapeHtml(btn.doctype)}">
              <span class="erp-quick-icon" aria-hidden="true">+</span>
              <span class="erp-quick-label">${escapeHtml(label)}</span>
            </button>`;
        }).join("")}
      </div>
    `;

    quickActions.addEventListener("click", event => {
      const btn = event.target.closest("[data-new-doc]");
      if (!btn) return;
      const doctype = btn.dataset.newDoc;
      if (window.frappe && typeof frappe.new_doc === "function") {
        frappe.new_doc(doctype);
      }
    });
  }

  /* ─────────────────────────────────────────
     ١٢. إنشاء بطاقات الوحدات والمربعات
  ───────────────────────────────────────── */

  function renderSections() {
    root.setAttribute("dir", isArabic ? "rtl" : "ltr");
    root.classList.toggle("erp-dashboard-rtl", isArabic);

    content.innerHTML = sections
      .map((section, sectionIndex) => {
        const sectionName = section[0];
        const sectionCards = section[1];

        const cardsHtml = sectionCards
          .map((card, cardIndex) => {
            const cardName = card[0];
            const icon = card[1];
            const items = card[2];

            const linksHtml = items.map(itemName => {
              const desc = itemDescriptions[itemName];
              const detailsLabel = isArabic ? "تفاصيل" : "Details";
              const infoBtn = desc
                ? `<button type="button" class="erp-info-link" data-info-item="${escapeHtml(itemName)}">${detailsLabel}</button>`
                : "";

              return `
                <div class="erp-link-row">
                  <button type="button" class="erp-link" data-route-name="${escapeHtml(itemName)}">
                    <span class="erp-link-text">${escapeHtml(translate(itemName))}</span>
                    <span class="erp-link-arrow" aria-hidden="true">${isArabic ? "←" : "→"}</span>
                  </button>
                  ${infoBtn}
                </div>`;
            }).join("");

            return `
              <article class="erp-card tone-${(sectionIndex + cardIndex) % 5}" data-erp-card>
                <button type="button" class="erp-card-heading" data-card-toggle aria-expanded="false">
                  <span class="erp-icon" aria-hidden="true">${icon}</span>
                  <span class="erp-card-title">${escapeHtml(translate(cardName))}</span>
                  <span class="erp-card-chevron" aria-hidden="true">⌄</span>
                </button>
                <div class="erp-card-links">${linksHtml}</div>
              </article>`;
          }).join("");

        return `
          <section class="erp-module-section">
            <h2 class="erp-section-title">${escapeHtml(translate(sectionName))}</h2>
            <div class="erp-dashboard-grid">${cardsHtml}</div>
          </section>`;
      }).join("");
  }

  /* ─────────────────────────────────────────
     ١٣. إنشاء الفوتر
  ───────────────────────────────────────── */

  function renderFooter() {
    if (!footerEl) return;
    const labels = footerInfo.labels;
    const phoneLabel = isArabic ? labels.phoneAr : labels.phoneEn;
    const emailLabel = isArabic ? labels.emailAr : labels.emailEn;
    const websiteLabel = isArabic ? labels.websiteAr : labels.websiteEn;

    footerEl.innerHTML = `
      <div class="erp-footer-inner">
        <div class="erp-footer-item">
          <span class="erp-footer-icon">📞</span>
          <span class="erp-footer-label">${escapeHtml(phoneLabel)}:</span>
          <a href="tel:${footerInfo.phone}" class="erp-footer-link" dir="ltr">${escapeHtml(footerInfo.phone)}</a>
        </div>
        <span class="erp-footer-sep">|</span>
        <div class="erp-footer-item">
          <span class="erp-footer-icon">✉️</span>
          <span class="erp-footer-label">${escapeHtml(emailLabel)}:</span>
          <a href="mailto:${footerInfo.email}" class="erp-footer-link">${escapeHtml(footerInfo.email)}</a>
        </div>
        <span class="erp-footer-sep">|</span>
        <div class="erp-footer-item">
          <span class="erp-footer-icon">🌐</span>
          <span class="erp-footer-label">${escapeHtml(websiteLabel)}:</span>
          <a href="https://${footerInfo.website}" class="erp-footer-link" target="_blank" rel="noopener">${escapeHtml(footerInfo.website)}</a>
        </div>
      </div>`;
  }

  /* ─────────────────────────────────────────
     ١٤. التوجيه وفتح الشاشات داخل النظام
  ───────────────────────────────────────── */

  function openRoute(name) {
    if (!window.frappe || typeof frappe.set_route !== "function") return;

    if (reportNames.has(name)) {
      frappe.set_route("query-report", name);
      return;
    }

    if (name === "Chart of Accounts") {
      frappe.set_route("Tree", "Account");
      return;
    }

    if (name === "Chart of Cost Centers") {
      frappe.set_route("Tree", "Cost Center");
      return;
    }

    if (name === "Bank Reconciliation Tool") {
      frappe.set_route("bank-reconciliation-tool");
      return;
    }

    if (name === "Opening Invoice Creation Tool") {
      frappe.set_route("Form", "Opening Invoice Creation Tool");
      return;
    }

    if (name === "Chart of Accounts Importer") {
      frappe.set_route("Form", "Chart of Accounts Importer");
      return;
    }

    if (singleDocs.has(name)) {
      frappe.set_route("Form", name);
      return;
    }

    if (treeDocs.has(name)) {
      frappe.set_route("Tree", name);
      return;
    }

    frappe.set_route("List", name);
  }

  /* ─────────────────────────────────────────
     ١٥. معالجة الأحداث والضغط
  ───────────────────────────────────────── */

  let lastToggleTime = 0;

  content.addEventListener("click", event => {
    const infoBtn = event.target.closest("[data-info-item]");
    if (infoBtn) {
      event.preventDefault();
      event.stopPropagation();
      showInfoModal(infoBtn.dataset.infoItem);
      return;
    }

    const link = event.target.closest("[data-route-name]");
    if (link) {
      event.preventDefault();
      openRoute(link.dataset.routeName);
      return;
    }

    const toggle = event.target.closest("[data-card-toggle]");
    if (toggle) {
      const now = Date.now();
      if (now - lastToggleTime < 300) return;
      lastToggleTime = now;

      const card = toggle.closest("[data-erp-card]");
      const expanded = toggle.getAttribute("aria-expanded") === "true";
      toggle.setAttribute("aria-expanded", String(!expanded));
      if (card) {
        card.classList.toggle("is-collapsed", expanded);
      }
    }
  });

  /* ─────────────────────────────────────────
     ١٦. التهيئة الأولية
  ───────────────────────────────────────── */

  renderStats();
  renderQuickActions();
  renderSections();
  renderFooter();
})();

style:
/* =========================================================

   MUBTKIR ERP — SALES WORKSPACE

   Unified Professional Brand Theme

========================================================= */





/* =========================================================

   1. ROOT + BRAND COLORS

========================================================= */



.erp-dashboard-wrapper {

  --brand-primary: #3867AE;

  --brand-secondary: #0F84B5;

  --brand-accent: #0BA1B8;

  --brand-purple: #644DA6;



  --brand-text: #243B63;

  --brand-muted: #66758A;



  --brand-border: rgba(56, 103, 174, 0.22);

  --brand-border-strong: rgba(56, 103, 174, 0.38);



  --brand-soft: rgba(56, 103, 174, 0.07);

  --brand-soft-secondary: rgba(15, 132, 181, 0.07);

  --brand-soft-accent: rgba(11, 161, 184, 0.07);

  --brand-soft-purple: rgba(100, 77, 166, 0.07);



  position: relative;

  isolation: isolate;



  width: 100%;



  padding: 14px 16px 36px;



  overflow: visible;



  color: var(--brand-text);

}





.erp-dashboard-wrapper,

.erp-dashboard-wrapper * {

  box-sizing: border-box;



  font-family:

    "Tajawal",

    "Inter",

    Arial,

    sans-serif !important;

}





/* RTL */



.erp-dashboard-wrapper.erp-dashboard-rtl {

  direction: rtl;

  text-align: right;

}





/* =========================================================

   2. BACKGROUND LOGO

========================================================= */



.erp-dashboard-bg {

  position: absolute;



  top: 150px;

  left: 50%;



  width: 58%;

  max-width: 720px;

  height: auto;



  object-fit: contain;



  transform: translateX(-50%);



  /*

   * وضوح الشعار المائي

   * ارفعها إلى 0.08 إذا أردته أوضح

   */

  opacity: 0.055;



  pointer-events: none;

  user-select: none;



  z-index: 0;

}





/* =========================================================

   3. CONTENT LAYER

========================================================= */



.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {

  position: relative;

  z-index: 2;

}





.erp-dashboard-content,

.erp-module-section,

.erp-dashboard-grid {

  background: transparent !important;

}





/* =========================================================

   4. STATISTICS GRID

========================================================= */



.erp-stats-grid {

  display: grid !important;



  grid-template-columns:

    repeat(4, minmax(0, 1fr)) !important;



  gap: 14px;



  margin: 18px 0 24px;

}





/* =========================================================

   5. STAT CARD

========================================================= */



.erp-stat-card {

  display: flex;



  align-items: center;



  gap: 12px;



  min-width: 0;



  padding: 16px 18px;



  border:

    1px solid var(--brand-border);



  border-radius: 14px;



  background:

    var(--fg-color, #ffffff);



  color:

    var(--brand-text) !important;



  box-shadow:

    0 4px 14px rgba(36, 59, 99, 0.06);



  transition:

    transform 0.22s ease,

    border-color 0.22s ease,

    box-shadow 0.22s ease;

}





@media (hover: hover) {



  .erp-stat-card:hover {

    transform:

      translateY(-3px);



    border-color:

      var(--brand-border-strong);



    box-shadow:

      0 10px 26px rgba(36, 59, 99, 0.11);

  }



}





/* =========================================================

   6. STAT ICON

========================================================= */



.erp-stat-icon {

  display: flex;



  align-items: center;

  justify-content: center;



  width: 44px;

  height: 44px;



  flex: 0 0 44px;



  border-radius: 12px;



  background:

    var(--brand-soft);



  font-size: 21px;

}





/* ألوان خلفيات الأيقونات فقط */



.erp-stat-card:nth-child(1)

.erp-stat-icon {

  background:

    var(--brand-soft);

}





.erp-stat-card:nth-child(2)

.erp-stat-icon {

  background:

    var(--brand-soft-secondary);

}





.erp-stat-card:nth-child(3)

.erp-stat-icon {

  background:

    var(--brand-soft-accent);

}





.erp-stat-card:nth-child(4)

.erp-stat-icon {

  background:

    var(--brand-soft-purple);

}





/* =========================================================

   7. STAT INFO

   جميع النصوص بلون موحد

========================================================= */



.erp-stat-info {

  display: flex;



  flex-direction: column;



  gap: 3px;



  min-width: 0;



  color:

    var(--brand-text) !important;

}





/* القيمة */



.erp-stat-value,

.erp-stat-card .erp-stat-value,

.erp-stat-card .erp-stat-info .erp-stat-value {

  color:

    var(--brand-text) !important;



  font-size:

    18px !important;



  font-weight:

    800 !important;



  line-height: 1.3;



  direction: ltr;

}





/* عنوان الإحصائية */



.erp-stat-label,

.erp-stat-card .erp-stat-label,

.erp-stat-card .erp-stat-info .erp-stat-label {

  color:

    var(--brand-text) !important;



  font-size:

    11.5px !important;



  font-weight:

    600 !important;



  line-height: 1.45;

}





/* =========================================================

   8. SECTION

========================================================= */



.erp-quick-actions {

  margin-bottom: 24px;

}





.erp-module-section {

  margin-top: 24px;

}





/* =========================================================

   9. SECTION TITLE

========================================================= */



.erp-section-title {

  position: relative;



  display: flex;



  align-items: center;



  min-height: 36px;



  margin: 0 0 14px;



  padding: 0 0 9px;



  border-bottom:

    1px solid var(--brand-border);



  color:

    var(--brand-text) !important;



  font-size: 18px;



  font-weight: 600;



  line-height: 1.4;

}





.erp-section-title::after {

  content: "";



  position: absolute;



  bottom: -1px;



  width: 52px;

  height: 2px;



  border-radius: 20px;



  background:

    var(--brand-primary);

}





.erp-dashboard-rtl

.erp-section-title::after {

  right: 0;

}





.erp-dashboard-wrapper:not(

  .erp-dashboard-rtl

)

.erp-section-title::after {

  left: 0;

}





/* =========================================================

   10. QUICK ACTIONS GRID

========================================================= */



.erp-quick-grid {

  display: grid !important;



  grid-template-columns:

    repeat(4, minmax(0, 1fr)) !important;



  gap: 12px;

}





/* =========================================================

   11. QUICK BUTTON

========================================================= */



.erp-quick-btn {

  display: flex;



  align-items: center;

  justify-content: center;



  min-height: 48px;



  padding:

    11px 14px;



  border:

    1px solid var(--brand-border);



  border-radius: 10px;



  outline: none;



  background:

    var(--brand-soft);



  color:

    var(--brand-primary) !important;



  font-family: inherit;



  font-size: 15px;



  font-weight: 700;



  line-height: 1.4;



  text-align: center;



  cursor: pointer;



  transition:

    transform 0.18s ease,

    background-color 0.18s ease,

    border-color 0.18s ease,

    color 0.18s ease,

    box-shadow 0.18s ease;

}





/* اختلاف الخلفيات فقط */



.erp-quick-btn:nth-child(2) {

  background:

    var(--brand-soft-secondary);

}





.erp-quick-btn:nth-child(3) {

  background:

    var(--brand-soft-accent);

}





.erp-quick-btn:nth-child(4) {

  background:

    var(--brand-soft-purple);

}





/* توحيد لون الخط */



.erp-quick-btn,

.erp-quick-btn .erp-quick-label {

  color:

    var(--brand-primary) !important;

}





@media (hover: hover) {



  .erp-quick-btn:hover {

    transform:

      translateY(-2px);



    color:

      var(--brand-secondary) !important;



    border-color:

      var(--brand-secondary);



    background:

      rgba(15, 132, 181, 0.10);



    box-shadow:

      0 6px 16px rgba(56, 103, 174, 0.12);

  }



}





.erp-quick-btn:active {

  transform:

    scale(0.98);

}





.erp-quick-label {

  width: 100%;



  white-space: normal;



  text-align: center;

}





/* =========================================================

   12. REPORT CARDS GRID

========================================================= */



.erp-dashboard-grid {

  display: grid !important;



  grid-template-columns:

    repeat(3, minmax(0, 1fr)) !important;



  align-items: start;



  gap: 16px;



  width: 100%;



  overflow: visible;

}





/* =========================================================

   13. REPORT CARD

========================================================= */



.erp-card {

  --erp-accent:

    var(--brand-primary);



  --erp-soft:

    var(--brand-soft);



  position: relative;



  z-index: 1;



  min-width: 0;



  min-height: 74px;

  max-height: 74px;



  padding:

    0 16px;



  overflow: hidden;



  border:

    1px solid var(--brand-border);



  border-radius: 14px;



  background:

    var(--fg-color, #ffffff);



  color:

    var(--brand-text) !important;



  box-shadow:

    0 5px 16px rgba(36, 59, 99, 0.06);



  transition:

    max-height 0.4s ease,

    transform 0.28s ease,

    box-shadow 0.28s ease,

    border-color 0.28s ease,

    padding-bottom 0.28s ease;

}





/* خلفية خفيفة */



.erp-card::before {

  content: "";



  position: absolute;



  inset: 0;



  z-index: 0;



  background:

    var(--erp-soft);



  opacity: 0;



  pointer-events: none;



  transition:

    opacity 0.25s ease;

}





/* الخط السفلي */



.erp-card::after {

  content: "";



  position: absolute;



  right: 0;

  bottom: 0;



  z-index: 4;



  width: 0;

  height: 3px;



  background:

    var(--erp-accent);



  transition:

    width 0.3s ease;

}





.erp-dashboard-wrapper:not(

  .erp-dashboard-rtl

)

.erp-card::after {

  right: auto;

  left: 0;

}





/* =========================================================

   14. CARD BRAND TONES

========================================================= */



.erp-card.tone-0 {

  --erp-accent:

    var(--brand-primary);



  --erp-soft:

    var(--brand-soft);

}





.erp-card.tone-1 {

  --erp-accent:

    var(--brand-secondary);



  --erp-soft:

    var(--brand-soft-secondary);

}





.erp-card.tone-2 {

  --erp-accent:

    var(--brand-accent);



  --erp-soft:

    var(--brand-soft-accent);

}





.erp-card.tone-3 {

  --erp-accent:

    var(--brand-purple);



  --erp-soft:

    var(--brand-soft-purple);

}





.erp-card.tone-4 {

  --erp-accent:

    var(--brand-primary);



  --erp-soft:

    var(--brand-soft);

}





/* =========================================================

   15. CARD OPEN

========================================================= */



.erp-card.is-open {

  z-index: 30;



  max-height: 590px;



  padding-bottom: 15px;



  border-color:

    var(--erp-accent);



  transform:

    translateY(-5px);



  box-shadow:

    0 18px 40px rgba(36, 59, 99, 0.14);

}





.erp-card.is-open::before {

  opacity: 1;

}





.erp-card.is-open::after {

  width: 100%;

}











/* =========================================================

   16. CARD HEADING

========================================================= */



.erp-card-heading {

  position: relative;



  z-index: 2;



  display: flex;



  align-items: center;



  gap: 8px;



  width: 100%;

  height: 72px;



  margin: 0;

  padding: 0;



  border: 0;



  border-bottom:

    1px solid transparent;



  outline: none;



  background:

    transparent;



  color:

    var(--brand-text) !important;



  font-family: inherit;



  text-align: inherit;



  cursor: pointer;



  transition:

    border-color 0.22s ease,

    margin-bottom 0.22s ease;

}





.erp-card.is-open

.erp-card-heading {

  margin-bottom: 10px;



  border-bottom-color:

    var(--brand-border);

}











/* =========================================================

   17. CARD TITLE

========================================================= */



.erp-card-title,

.erp-card .erp-card-title {

  flex: 1;



  min-width: 0;



  color:

    var(--brand-text) !important;



  font-size: 16px;



  font-weight: 800;



  line-height: 1.5;

}





/* =========================================================

   18. CARD CHEVRON

========================================================= */



.erp-card-chevron {

  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 28px;

  height: 28px;



  flex: 0 0 28px;



  border-radius: 8px;



  background:

    var(--erp-soft);



  color:

    var(--erp-accent) !important;



  font-size: 17px;



  transition:

    transform 0.22s ease;

}





.erp-card.is-open

.erp-card-chevron {

  transform:

    rotate(180deg);

}











/* =========================================================

   19. CARD LINKS

========================================================= */



.erp-card-links {

  position: relative;



  z-index: 2;



  display: grid;



  gap: 5px;



  max-height: 0;



  margin: 0;

  padding: 0;



  overflow: hidden;



  opacity: 0;



  visibility: hidden;



  pointer-events: none;



  transform:

    translateY(-8px);



  transition:

    max-height 0.38s ease,

    opacity 0.2s ease,

    visibility 0.2s ease,

    transform 0.28s ease;

}





.erp-card.is-open

.erp-card-links {

  max-height: 480px;



  overflow-y: auto;



  opacity: 1;



  visibility: visible;



  pointer-events: auto;



  transform:

    translateY(0);

}











/* =========================================================

   20. LINK ROW

========================================================= */



.erp-link-row {

  display: flex;



  align-items: center;



  gap: 6px;



  width: 100%;

}





/* =========================================================

   21. CARD LINK

========================================================= */



.erp-link {

  display: flex;



  align-items: center;



  gap: 7px;



  flex: 1;



  min-width: 0;



  min-height: 36px;



  padding:

    7px 10px;



  border:

    1px solid transparent;



  border-radius: 8px;



  outline: none;



  background:

    transparent;



  color:

    var(--brand-text) !important;



  font-family: inherit;



  font-size: 13px;



  font-weight: 500;



  line-height: 1.45;



  text-align: inherit;



  cursor: pointer;



  transition:

    background 0.16s ease,

    color 0.16s ease,

    border-color 0.16s ease,

    transform 0.16s ease;

}





.erp-link-text {

  flex: 1;



  min-width: 0;



  color:

    inherit !important;

}





.erp-link:hover,

.erp-link:focus {

  border-color:

    color-mix(

      in srgb,

      var(--erp-accent) 28%,

      transparent

    );



  background:

    var(--erp-soft);



  color:

    var(--erp-accent) !important;

}





.erp-dashboard-rtl

.erp-link:hover,



.erp-dashboard-rtl

.erp-link:focus {

  transform:

    translateX(-3px);

}





.erp-dashboard-wrapper:not(

  .erp-dashboard-rtl

)

.erp-link:hover,



.erp-dashboard-wrapper:not(

  .erp-dashboard-rtl

)

.erp-link:focus {

  transform:

    translateX(3px);

}





/* =========================================================

   22. LINK ARROW

========================================================= */



.erp-link-arrow {

  flex: 0 0 auto;



  color:

    var(--erp-accent) !important;



  font-size: 13px;



  font-weight: 800;



  opacity: 0;



  transition:

    opacity 0.16s ease;

}





.erp-link:hover

.erp-link-arrow,



.erp-link:focus

.erp-link-arrow {

  opacity: 1;

}





/* =========================================================

   23. DETAILS BUTTON

========================================================= */



.erp-info-link {

  flex: 0 0 auto;



  padding:

    5px 10px;



  border:

    1px solid var(--brand-border);



  border-radius: 7px;



  outline: none;



  background:

    var(--brand-soft);



  color:

    var(--brand-primary) !important;



  font-family: inherit;



  font-size: 12px;



  font-weight: 600;



  cursor: pointer;



  transition:

    border-color 0.16s ease,

    background 0.16s ease,

    color 0.16s ease;

}





.erp-info-link:hover {

  border-color:

    var(--brand-primary);



  background:

    rgba(56, 103, 174, 0.13);



  color:

    var(--brand-primary) !important;

}





/* =========================================================

   24. SCROLLBAR

========================================================= */



.erp-card-links::-webkit-scrollbar {

  width: 5px;

}





.erp-card-links::-webkit-scrollbar-track {

  background:

    transparent;

}





.erp-card-links::-webkit-scrollbar-thumb {

  border-radius: 10px;



  background:

    var(--brand-primary);

}





/* =========================================================

   25. FOOTER

   ★ حجم خط الفوتر من هنا ★

========================================================= */



.erp-footer {



  /* غيّر هذه القيمة فقط */

  --footer-font-size: 15px;



  margin-top: 34px;



  padding:

    20px 12px 4px;



  border-top:

    1px solid var(--brand-border);



  color:

    var(--brand-text);

}





.erp-footer-inner {

  display: flex;



  align-items: center;

  justify-content: center;



  flex-wrap: wrap;



  gap:

    10px 22px;



  width: 100%;

}





.erp-footer-item {

  display: flex;



  align-items: center;



  gap: 7px;



  color:

    var(--brand-text) !important;



  font-size:

    var(--footer-font-size) !important;



  font-weight: 600;



  line-height: 1.6;

}





.erp-footer-icon {

  font-size:

    17px !important;



  line-height: 1;

}





.erp-footer-label {

  color:

    var(--brand-text) !important;



  font-size:

    var(--footer-font-size) !important;



  font-weight:

    700 !important;

}





.erp-footer-link {

  color:

    var(--brand-primary) !important;



  font-size:

    var(--footer-font-size) !important;



  font-weight:

    600 !important;



  text-decoration: none;



  transition:

    color 0.18s ease;

}





.erp-footer-link:hover {

  color:

    var(--brand-secondary) !important;



  text-decoration:

    underline;

}





.erp-footer-sep {

  color:

    var(--brand-border-strong) !important;



  font-size: 20px;



  font-weight: 300;



  line-height: 1;

}





/* =========================================================

   26. MODAL OVERLAY

========================================================= */



.erp-modal-overlay {

  position: fixed;



  inset: 0;



  z-index:

    99999 !important;



  display: flex;



  align-items: center;

  justify-content: center;



  padding: 20px;



  background:

    rgba(12, 27, 54, 0) !important;



  transition:

    background 0.28s ease;

}





.erp-modal-overlay.is-visible {

  background:

    rgba(12, 27, 54, 0.52) !important;

}





/* =========================================================

   27. MODAL BOX

========================================================= */



.erp-modal-box {

  position: relative;



  width: 100%;



  max-width: 480px;

  max-height: 85vh;



  padding:

    28px 24px;



  overflow-y: auto;



  border:

    1px solid var(--brand-border);



  border-radius: 16px;



  background:

    #ffffff !important;



  box-shadow:

    0 24px 64px rgba(12, 27, 54, 0.28) !important;



  opacity: 0;



  transform:

    translateY(24px)

    scale(0.97);



  transition:

    opacity 0.28s ease,

    transform 0.28s ease;

}





.erp-modal-overlay.is-visible

.erp-modal-box {

  opacity: 1;



  transform:

    translateY(0)

    scale(1);

}





/* =========================================================

   28. MODAL CLOSE

========================================================= */



.erp-modal-close {

  position: absolute;



  top: 12px;



  display: flex;



  align-items: center;

  justify-content: center;



  width: 32px;

  height: 32px;



  border: 0;



  border-radius: 8px;



  background:

    var(--brand-soft);



  color:

    var(--brand-primary) !important;



  font-size: 15px;



  cursor: pointer;

}





[dir="rtl"]

.erp-modal-close {

  left: 12px;

}





[dir="ltr"]

.erp-modal-close {

  right: 12px;

}





/* =========================================================

   29. MODAL CONTENT

========================================================= */



.erp-modal-header {

  display: flex;



  align-items: center;



  gap: 11px;



  margin-bottom: 15px;

}





.erp-modal-icon {

  font-size: 28px;



  line-height: 1;

}





.erp-modal-title {

  margin: 0;



  color:

    var(--brand-text) !important;



  font-size: 18px;



  font-weight: 800;

}





.erp-modal-summary {

  margin:

    0 0 16px;



  color:

    var(--brand-text) !important;



  font-size: 13.5px;



  line-height: 1.75;

}





/* =========================================================

   30. MODAL STEP BUTTON

========================================================= */



.erp-modal-toggle-steps {

  display: inline-flex;



  align-items: center;



  gap: 6px;



  padding:

    8px 16px;



  border:

    1px solid var(--brand-primary);



  border-radius: 9px;



  background:

    var(--brand-soft);



  color:

    var(--brand-primary) !important;



  font-family: inherit;



  font-size: 12.5px;



  font-weight: 700;



  cursor: pointer;

}





.erp-modal-toggle-steps:hover {

  background:

    rgba(56, 103, 174, 0.13);

}





/* =========================================================

   31. MODAL STEPS

========================================================= */



.erp-modal-steps {

  max-height: 0;



  overflow: hidden;



  opacity: 0;



  margin-top: 0;



  transition:

    max-height 0.38s ease,

    opacity 0.25s ease,

    margin-top 0.25s ease;

}





.erp-modal-steps.is-shown {

  max-height: 500px;



  opacity: 1;



  margin-top: 15px;

}





.erp-modal-steps-list {

  margin: 0;



  padding:

    0 20px;



  list-style: none;



  counter-reset:

    step-counter;

}





.erp-modal-steps-list li {

  position: relative;



  counter-increment:

    step-counter;



  padding:

    9px 0;



  border-bottom:

    1px solid rgba(56, 103, 174, 0.10);



  color:

    var(--brand-text) !important;



  font-size: 12.5px;



  line-height: 1.65;

}





.erp-modal-steps-list li:last-child {

  border-bottom: 0;

}





.erp-modal-steps-list li::before {

  content:

    counter(step-counter);



  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 22px;

  height: 22px;



  margin-inline-end: 9px;



  border-radius: 50%;



  background:

    var(--brand-primary);



  color:

    #ffffff;



  font-size: 10px;



  font-weight: 800;

}





/* =========================================================

   32. DARK MODE

========================================================= */



[data-theme="dark"]

.erp-dashboard-wrapper,



html[data-theme="dark"]

.erp-dashboard-wrapper {



  --brand-text:

    #E9EEF7;



  --brand-muted:

    #A7B2C5;



  --brand-border:

    rgba(15, 132, 181, 0.22);



  --brand-border-strong:

    rgba(15, 132, 181, 0.40);

}





[data-theme="dark"]

.erp-card,



html[data-theme="dark"]

.erp-card,



[data-theme="dark"]

.erp-stat-card,



html[data-theme="dark"]

.erp-stat-card {



  background:

    var(--fg-color, #20242c);



  box-shadow:

    0 7px 22px rgba(0, 0, 0, 0.18);

}





[data-theme="dark"]

.erp-modal-box,



html[data-theme="dark"]

.erp-modal-box {



  background:

    var(--fg-color, #20242c) !important;

}





/* =========================================================

   33. TABLET

========================================================= */



@media (max-width: 1050px) {



  .erp-dashboard-grid {

    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;

  }



}





/* =========================================================

   34. SMALL TABLET

========================================================= */



@media (max-width: 850px) {



  .erp-stats-grid {

    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;

  }





  .erp-quick-grid {

    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;

  }



}





/* =========================================================

   35. MOBILE

========================================================= */



@media (max-width: 650px) {



  .erp-dashboard-wrapper {

    padding:

      8px 8px 26px;

  }





  .erp-dashboard-bg {

    display: none;

  }





  .erp-stats-grid {

    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;



    gap: 9px;



    margin:

      12px 0 18px;

  }





  .erp-stat-card {

    padding: 11px;



    gap: 8px;

  }





  .erp-stat-icon {

    width: 36px;

    height: 36px;



    flex:

      0 0 36px;



    font-size: 17px;

  }





  .erp-stat-value,

  .erp-stat-card

  .erp-stat-value {

    font-size:

      14px !important;

  }





  .erp-stat-label,

  .erp-stat-card

  .erp-stat-label {

    font-size:

      10px !important;

  }





  .erp-quick-grid {

    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;



    gap: 8px;

  }





  .erp-quick-btn {

    min-height: 43px;



    padding:

      9px 7px;



    font-size: 11.5px;

  }





  .erp-dashboard-grid {

    grid-template-columns:

      1fr !important;



    gap: 11px;

  }





  .erp-card.is-open {

    transform:

      translateY(-2px);

  }





  /* Footer Mobile */



  .erp-footer {

    --footer-font-size: 13px;



    margin-top: 26px;



    padding-top: 16px;

  }





  .erp-footer-inner {

    flex-direction: column;



    gap: 8px;

  }





  .erp-footer-item {

    justify-content: center;

  }





  .erp-footer-icon {

    font-size:

      15px !important;

  }





  .erp-footer-sep {

    display: none;

  }





  .erp-modal-overlay {

    align-items:

      flex-end;



    padding: 10px;

  }





  .erp-modal-box {

    max-height: 82vh;



    padding:

      22px 17px;



    border-radius:

      16px 16px 0 0;

  }



}

/* =========================================================
   CARDS REMAIN OPEN BY DEFAULT & HOVER-OPEN DISABLED
   إبقاء المربعات مفتوحة بشكل تلقائي وإلغاء الفتح بمرور الماوس
========================================================= */

.erp-card {
  max-height: none !important;
  overflow: visible !important;
  padding-bottom: 15px !important;
}

.erp-card .erp-card-heading {
  margin-bottom: 10px !important;
  border-bottom: 1px solid var(--brand-border) !important;
}

.erp-card .erp-card-chevron {
  transform: rotate(180deg) !important;
}

.erp-card .erp-card-links {
  max-height: none !important;
  overflow: visible !important;
  opacity: 1 !important;
